window.VeilGardeData.files["Sources-VeilGardeCLI"] = {"group":"Sources-VeilGardeCLI","files":[{"path":"Sources/VeilGardeCLI/Commands/Bundle.swift","status":"added","lang":"swift","hunks":[[1,0,1,109]],"header":{"lines":[1,11],"target":"VeilGardeCLI","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1561,"scopes":[["S","BundleCommand",null,"",17,17,[17,38],109,null,-1,0,"a"],["f","directory",["_"],"static",21,21,[21,50],23,null,0,0,"a"],["S","Show",null,"",25,25,[25,33],42,null,0,0,"a"],["f","run",[],"",29,29,[29,26],41,null,2,0,"a"],["S","Verify",null,"",44,44,[44,35],54,null,0,0,"a"],["f","run",[],"",48,48,[48,26],53,null,4,0,"a"],["S","Diff",null,"",56,56,[56,33],76,null,0,0,"a"],["f","run",[],"",61,61,[61,26],75,null,6,0,"a"],["S","Derive",null,"",78,78,[78,35],108,null,0,0,"a"],["f","run",[],"",89,89,[89,26],107,null,8,0,"a"]],"old":"","new":"//\n//  Bundle.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde bundle`: what a detector bundle holds. `show` lists its artifacts by role with\n//        their hashes, sizes and provenance; `verify` re-hashes every file against the manifest;\n//        `diff` names the roles whose bytes differ between two bundles (the shipped one by default),\n//        which is what a promote would change; `derive` makes a measurement variant of a bundle,\n//        its combiner edited, re-pinned and recorded (BundleDerivation).\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct BundleCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"bundle\", abstract: \"Show, verify and diff detector bundles (manifest.json and its artifacts).\",\n                                                    subcommands: [Show.self, Verify.self, Diff.self, Derive.self])\n\n    static func directory(_ path: String?) -> URL {\n        path.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) } ?? ShippedBundle.directory\n    }\n\n    struct Show: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"show\", abstract: \"List a bundle's artifacts and expected weights (default: the shipped bundle).\")\n        @Argument(help: \"A bundle directory.\") var path: String?\n\n        func run() throws {\n            guarded {\n                let bundle = try ModelBundle.load(BundleCommand.directory(path), verify: false)\n                print(\"bundle \\(bundle.root.path)  (\\(bundle.manifest.format))\")\n                for a in bundle.manifest.artifacts {\n                    print(\"  \" + a.slot.padding(toLength: 22, withPad: \" \", startingAt: 0) + a.file.padding(toLength: 36, withPad: \" \", startingAt: 0)\n                          + \"\\(a.sha256.prefix(12))  \\(ByteCountFormatter.string(fromByteCount: Int64(a.bytes), countStyle: .file))\" + (a.frozen ? \"  frozen\" : \"\")\n                          + (a.source.map { \"  ← \\($0)\" } ?? \"\"))\n                }\n                for w in bundle.manifest.weights { print(\"  weight \" + w.file.padding(toLength: 36, withPad: \" \", startingAt: 0) + \"\\(w.sha256.prefix(12))\") }\n                for e in bundle.manifest.history { print(\"  \\(ISO8601DateFormatter().string(from: e.date))  \\(e.kind.rawValue)  \\(e.slot)\" + (e.note.map { \"  \\($0)\" } ?? \"\")) }\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Re-hash every artifact of a bundle against its manifest.\")\n        @Argument(help: \"A bundle directory.\") var path: String?\n\n        func run() throws {\n            guarded {\n                let bundle = try ModelBundle.load(BundleCommand.directory(path))\n                print(\"ok  \\(bundle.manifest.artifacts.count) artifacts verified in \\(bundle.root.path)\")\n            }\n        }\n    }\n\n    struct Diff: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"diff\", abstract: \"Name the roles whose bytes differ between two bundles.\")\n        @Argument(help: \"The bundle to compare.\") var path: String\n        @Argument(help: \"The bundle to compare against (default: the shipped bundle).\") var base: String?\n\n        func run() throws {\n            guarded {\n                let a = try ModelBundle.load(BundleCommand.directory(base), verify: false).manifest\n                let b = try ModelBundle.load(BundleCommand.directory(path), verify: false).manifest\n                let slots = Set(a.artifacts.map(\\.slot)).union(b.artifacts.map(\\.slot)).sorted()\n                var changed = 0\n                for slot in slots {\n                    let x = a.artifact(slot: slot), y = b.artifact(slot: slot)\n                    guard x?.sha256 != y?.sha256 else { continue }\n                    changed += 1\n                    print(\"  \" + slot.padding(toLength: 22, withPad: \" \", startingAt: 0) + \"\\(x?.sha256.prefix(12) ?? \"absent\") → \\(y?.sha256.prefix(12) ?? \"absent\")\")\n                }\n                print(changed == 0 ? \"no artifact differs\" : \"\\(changed) role(s) differ\")\n            }\n        }\n    }\n\n    struct Derive: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"derive\", abstract: \"Make a measurement variant of a bundle under <work area>/candidates/<id>: its combiner edited, re-pinned and recorded.\",\n            discussion: \"Edits: combiner.w_np=null (the noiseprint does not run), or combiner.w_np, combiner.w_rescue, combiner.w_gen[0-2] set to a value ≥ 0. Nothing is promoted.\")\n        @Option(help: \"The parent: a bundle directory, shipped, or live.\") var from: String\n        @Option(help: \"The variant's candidate id.\") var id: String\n        @Option(name: .customLong(\"set\"), help: \"An edit; repeatable.\") var edits: [String]\n        @Option(help: \"Why, recorded with the edit.\") var note: String\n        @Flag(help: \"Replace a candidate of the same id.\") var replace = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                let root = from == \"shipped\" ? ShippedBundle.directory : from == \"live\" ? area.live : BundleCommand.directory(from)\n                let parent = try ModelBundle.load(root)\n                let parsed = try edits.map(CombinerEdit.parse)\n                let candidate = try BundleDerivation.derive(id: id, in: area, from: parent, edits: parsed, note: note, replacing: replace)\n                print(\"derived \\(candidate.root.path) from \\(parent.root.path): \\(parsed.map(\\.description).joined(separator: \", \"))\")\n                for artifact in candidate.manifest.artifacts where artifact.sha256 != parent.manifest.artifact(slot: artifact.slot)?.sha256 {\n                    print(\"  \" + artifact.slot.padding(toLength: 22, withPad: \" \", startingAt: 0)\n                          + \"\\(parent.manifest.artifact(slot: artifact.slot)?.sha256.prefix(12) ?? \"absent\") → \\(artifact.sha256.prefix(12))\")\n                }\n                if let url = candidate.url(.combiner) {\n                    let c = try StackCombiner.load(url)\n                    print(String(format: \"  combiner: w0 %.4f, w_base %.4f, w_gen [%@], w_rescue %.3f, w_np %@\", c.w0, c.wBase,\n                                 c.wGen.map { String(format: \"%.4f\", $0) }.joined(separator: \", \"), c.wRescue, c.wNp.map { String(format: \"%.3f\", $0) } ?? \"absent\"))\n                }\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Doctor.swift","status":"added","lang":"swift","hunks":[[1,0,1,29]],"header":{"lines":[1,9],"target":"VeilGardeCLI","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1571,"scopes":[["S","DoctorCommand",null,"",15,15,[15,38],29,null,-1,0,"a"],["f","run",[],"",20,20,[20,22],28,null,0,0,"a"]],"old":"","new":"//\n//  Doctor.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde doctor`: the checks before anything else. The checks live in the VeilGarde\n//        umbrella (Doctor), so every layer adds its own; a failed check says what is missing and\n//        the command exits 1.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct DoctorCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"doctor\", abstract: \"Check the setup: Metal library, work area, free space, bundle, weights.\")\n\n    @OptionGroup var workArea: WorkAreaOptions\n\n    func run() throws {\n        print(\"veilgarde doctor\")\n        let options = workArea\n        let checks = Doctor.run(area: Result { try options.resolve() })\n        for check in checks { print(check.line) }\n        let failures = checks.filter { !$0.ok }.count\n        print(failures == 0 ? \"all checks passed\" : \"\\(failures) check(s) failed\")\n        if failures > 0 { throw ArgumentParser.ExitCode(FailureCode.doctor.rawValue) }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Features.swift","status":"added","lang":"swift","hunks":[[1,0,1,171]],"header":{"lines":[1,13],"target":"VeilGardeCLI","what":[6,12],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1573,"scopes":[["S","FeaturesCommand",null,"",19,19,[19,40],171,null,-1,0,"a"],["S","Capture",null,"",24,24,[24,36],35,null,0,0,"a"],["f","run",[],"",29,29,[29,26],34,null,1,0,"a"],["S","Show",null,"",37,37,[37,33],78,null,0,0,"a"],["f","run",[],"",45,45,[45,26],77,null,3,0,"a"],["S","Tiles",null,"",80,80,[80,34],99,null,0,0,"a"],["f","run",[],"",87,87,[87,26],98,null,5,0,"a"],["S","Patches",null,"",101,101,[101,36],121,null,0,0,"a"],["f","run",[],"",107,107,[107,26],120,null,7,0,"a"],["S","Extract",null,"",123,123,[123,36],170,null,0,0,"a"],["f","run",[],"",136,136,[136,26],169,null,9,0,"a"]],"old":"","new":"//\n//  Features.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde features`: what the lens measures on one image, without a verdict. `capture`\n//        prints the capture signature as Garde's --capture TSV (peak, valid, native px, present);\n//        `show` prints the capture values, the screenshot gate's tells and the 19 warp features'\n//        means (or every tile with --tiles, or JSON). `tiles` cuts a dataset into the warp\n//        trainer's tile cache and `patches` the noiseprint trainer's patches into its cache, both\n//        ahead of training; `extract` measures labeled images into a new store shard (the six\n//        columns every head and the fusion head train on) and keeps nothing of the images.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct FeaturesCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"features\", abstract: \"Measure an image's features: the capture signature, the screenshot gate, the warp tile features.\",\n        subcommands: [Capture.self, Show.self, Tiles.self, Patches.self, Extract.self])\n\n    struct Capture: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"capture\", abstract: \"Print the native capture signature as a TSV line: peak, valid, native px, present.\")\n\n        @Argument(help: \"The image.\") var image: String\n\n        func run() throws {\n            guarded {\n                let cs = CaptureLens.signature(try loadImage(image))\n                print(String(format: \"%.3f\\t%@\\t%d\\t%@\", cs.peak, cs.valid ? \"true\" : \"false\", cs.nativePixels, cs.present ? \"true\" : \"false\"))\n            }\n        }\n    }\n\n    struct Show: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"show\", abstract: \"Show the capture values, the screenshot gate and the warp tile features of an image.\")\n\n        @Argument(help: \"The image.\") var image: String\n        @Flag(help: \"Every tile's 19 features, not their means.\") var tiles = false\n        @Flag(help: \"One JSON object instead of text.\") var json = false\n        @Flag(name: .customLong(\"exact-warp\"), help: \"Exact double warp coordinates (debugging only).\") var exactWarp = false\n\n        func run() throws {\n            guarded {\n                let cg = try loadImage(image)\n                let capture = CaptureLens.features(cg)\n                let gate = ScreenshotLens.gate(cg)\n                let (map, geometry) = try WarpLens.tileFeatures(cgImage: cg, quantizeLikeCV2: !exactWarp)\n                var means = [Double](repeating: 0, count: map.featureCount)\n                for t in 0..<map.count { for (k, v) in map.row(t).enumerated() { means[k] += Double(v) } }\n                means = means.map { $0 / Double(max(1, map.count)) }\n                if json {\n                    var object: [String: Any] = [\n                        \"image\": [\"width\": cg.width, \"height\": cg.height, \"scored_width\": geometry.scoringWidth, \"scored_height\": geometry.scoringHeight],\n                        \"capture\": Dictionary(uniqueKeysWithValues: zip(CaptureFeatures.names, capture.asVector.map(Double.init))),\n                        \"screenshot_gate\": [\"is_screenshot\": gate.isScreenshot, \"grad_zero\": Double(gate.gradZero), \"flat_strict\": Double(gate.flatStrict), \"top_color\": Double(gate.topColor)],\n                        \"warp_feature_means\": Dictionary(uniqueKeysWithValues: zip(WarpFeatures.names, means)),\n                        \"tile_grid\": [\"rows\": map.tileRows, \"cols\": map.tileCols],\n                    ]\n                    if tiles { object[\"tiles\"] = map.rowsArray.map { $0.map(Double.init) } }\n                    try emitJSON(try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys]), to: \"-\")\n                    return\n                }\n                print(\"\\(URL(fileURLWithPath: image).lastPathComponent): \\(cg.width)×\\(cg.height), scored \\(geometry.scoringWidth)×\\(geometry.scoringHeight), \\(map.tileRows)×\\(map.tileCols) tiles\")\n                print(\"\\ncapture (native, fusion columns 386–394)\")\n                for (name, value) in zip(CaptureFeatures.names, capture.asVector) { print(\"  \\(name.padding(toLength: 12, withPad: \" \", startingAt: 0)) \\(value)\") }\n                print(\"\\nscreenshot gate  \\(gate.isScreenshot ? \"fires\" : \"quiet\")  grad_zero \\(gate.gradZero)  flat_strict \\(gate.flatStrict)  top_color \\(gate.topColor)\")\n                print(\"\\nwarp features (mean over \\(map.count) tiles)\")\n                for (name, value) in zip(WarpFeatures.names, means) { print(\"  \\(name.padding(toLength: 12, withPad: \" \", startingAt: 0)) \\(String(format: \"%.6f\", value))\") }\n                if tiles {\n                    print(\"\\n\" + ([\"tile\"] + WarpFeatures.names).joined(separator: \"\\t\"))\n                    for t in 0..<map.count { print(([String(t)] + map.row(t).map { String(format: \"%.6g\", $0) }).joined(separator: \"\\t\")) }\n                }\n            }\n        }\n    }\n\n    struct Tiles: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"tiles\", abstract: \"Cut a dataset's images into the warp trainer's tile cache (resumable).\")\n        @Argument(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl.\") var dataset: String\n        @Option(name: .customLong(\"sample-per-label\"), help: \"At most this many images of each label.\") var samplePerLabel: Int?\n        @Option(help: \"The sample's seed.\") var seed: UInt64 = 0\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let engine = TrainingEngine(area: try workArea.resolve(), parent: ShippedBundle.directory)\n                let url = datasetURL(dataset)\n                let manifest = try engine.manifest(for: url, samplePerLabel: samplePerLabel, seed: seed)\n                let cache = engine.tileCache(for: url)\n                note(\"tiles: \\(manifest.count) images → \\(cache.directory.path)\")\n                let report = try TileExtractor.extract(manifest, into: cache, note: note)\n                print(String(format: \"%d images cut (%d tiles), %d already cached, %d skipped, %.1fs → %@\", report.images, report.tiles,\n                             report.skippedCached, report.failed.count, report.seconds, cache.directory.path))\n            }\n        }\n    }\n\n    struct Patches: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"patches\", abstract: \"Cut the noiseprint trainer's patches into the work area's cache (CPU only), ahead of `train noiseprint`.\")\n        @Option(name: .customLong(\"per-family\"), help: \"Images per negative family (three quarters train), as `train noiseprint` takes it.\") var perFamily: Int = 120\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                var settings = NoiseprintSettings()\n                settings.sources.perFamily = perFamily\n                let directory = NoiseprintTrainer.cacheDirectory(try workArea.resolve())\n                let started = Date()\n                let (split, cut) = try NoiseprintTrainer.cut(settings: settings, cacheDirectory: directory, note: note)\n                print(\"camera \\(split.cameraTrain.count) train / \\(split.cameraTest.count) test; \" + settings.sources.negatives.map {\n                    \"\\($0.name) \\(split.counts[$0.name]?[1] ?? 0)/\\(split.counts[$0.name]?[2] ?? 0)\" }.joined(separator: \", \"))\n                print(String(format: \"%d patches a class (cut: camera %d, negatives %d), %@, %.0fs → %@\", cut.set.count / 2, cut.cameraCut, cut.negativeCut,\n                             cut.hit ? \"read from the cache\" : \"cut and cached\", Date().timeIntervalSince(started), cut.cache?.path ?? \"no cache\"))\n                if !cut.failed.isEmpty { print(\"\\(cut.failed.count) images could not be read: \" + cut.failed.prefix(5).joined(separator: \"; \")) }\n            }\n        }\n    }\n\n    struct Extract: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"extract\", abstract: \"Measure labeled images into a new feature-store shard; the images are read and dropped.\")\n        @Argument(help: \"A folder of images, a text file of paths, or a .jsonl of {path, label, category, source?, golden?, gen_family?}.\") var input: String\n        @Option(help: \"The new shard's name.\") var shard: String\n        @Option(help: \"The label for a folder or path list: 1 generated, 0 real.\") var label: Int?\n        @Option(help: \"The category for a folder or path list (art, blur, human, cgi, preview, photo, …).\") var category: String?\n        @Option(help: \"The source tag for a folder or path list.\") var source: String?\n        @Option(help: \"The feature store directory (default: <work area>/store/shards).\") var store: String?\n        @Option(help: \"Read at most this many images.\") var limit: Int?\n        @Option(help: \"small, xsmall or xxsmall.\") var dino: String = DinoVariant.small.rawValue\n        @Option(help: \"Measure only these columns, comma separated (dino_norm, dino_fusion, cap, warp, sharp, noiseprint); the rest are NaN.\") var columns: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino is small, xsmall or xxsmall\") }\n                let measured = try columns.map { list in\n                    Set(try list.split(separator: \",\").map { name -> FeatureColumn in\n                        let trimmed = name.trimmingCharacters(in: .whitespaces)\n                        guard let column = FeatureColumn(rawValue: trimmed) else {\n                            throw VeilGardeFailure.usage(\"--columns names \\(FeatureColumn.allCases.map(\\.rawValue).joined(separator: \", \")), not \\(trimmed)\")\n                        }\n                        return column\n                    })\n                } ?? Set(FeatureColumn.allCases)\n                let url = datasetURL(input)\n                var items: [ExtractionItem]\n                if url.pathExtension == \"jsonl\" {\n                    items = try JSONCoding.readLines(ExtractionItem.self, from: url)\n                } else {\n                    guard let label, let category else { throw VeilGardeFailure.usage(\"a folder or a path list needs --label and --category\") }\n                    var isDirectory: ObjCBool = false\n                    FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory)\n                    let paths = isDirectory.boolValue ? ShardExtractor.images(in: url).map(\\.path)\n                        : try String(contentsOf: url, encoding: .utf8).split(separator: \"\\n\").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }\n                    items = paths.map { ExtractionItem(path: $0, label: label, category: category, source: source) }\n                }\n                if let limit { items = Array(items.prefix(limit)) }\n                let storeURL = try store.map(datasetURL) ?? workArea.resolve().root.appendingPathComponent(\"store/shards\", isDirectory: true)\n                let extractor = try FeatureExtractor(warpModelURL: ShippedBundle.url(.warpTile), variant: variant, columns: measured)\n                note(\"extract: \\(items.count) images → \\(storeURL.path)/\\(shard)\")\n                let report = try ShardExtractor.extract(items, shard: shard, store: FeatureStore(directory: storeURL), extractor: extractor, note: note)\n                print(String(format: \"%@: %d rows written, %d already in the store, %d skipped, %.1fs\", report.shard, report.rows, report.skippedKnown,\n                             report.failed.count, report.seconds))\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Flywheel.swift","status":"added","lang":"swift","hunks":[[1,0,1,299]],"header":{"lines":[1,15],"target":"VeilGardeCLI","what":[6,12],"pin":[13,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1584,"scopes":[["S","FlywheelCommand",null,"",21,21,[21,40],299,null,-1,0,"a"],["f","area",["_"],"static",27,27,[27,72],27,null,0,8,"a"],["f","battery",["_"],"static",30,30,[30,66],40,[29,29],0,0,"a"],["S","Init",null,"",42,42,[42,33],63,null,0,0,"a"],["f","run",[],"",48,48,[48,26],62,null,3,0,"a"],["S","Seed",null,"",65,65,[65,33],77,null,0,0,"a"],["f","run",[],"",70,70,[70,26],76,null,5,0,"a"],["S","Acquire",null,"",79,79,[79,36],118,null,0,0,"a"],["f","run",[],"",89,89,[89,26],117,null,7,0,"a"],["S","Gap",null,"",120,120,[120,32],141,null,0,0,"a"],["f","run",[],"",126,126,[126,26],140,null,9,0,"a"],["S","IngestImages",null,"",143,143,[143,41],158,null,0,0,"a"],["f","run",[],"",149,149,[149,26],157,null,11,0,"a"],["S","Candidates",null,"",160,160,[160,39],187,null,0,0,"a"],["f","run",[],"",168,168,[168,26],186,null,13,0,"a"],["S","AgreementCommand",null,"",189,189,[189,45],208,null,0,0,"a"],["f","run",[],"",195,195,[195,26],207,null,15,0,"a"],["S","Battery",null,"",210,210,[210,36],241,null,0,0,"a"],["f","run",[],"",220,220,[220,26],240,null,17,0,"a"],["S","Promote",null,"",243,243,[243,36],264,null,0,0,"a"],["f","run",[],"",250,250,[250,26],263,null,19,0,"a"],["S","Rollback",null,"",266,266,[266,37],279,null,0,0,"a"],["f","run",[],"",271,271,[271,26],278,null,21,0,"a"],["S","Status",null,"",281,281,[281,35],298,null,0,0,"a"],["f","run",[],"",285,285,[285,26],297,null,23,0,"a"]],"old":"","new":"//\n//  Flywheel.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde flywheel`: the specialist-head regime on the work area. `init` seeds the live\n//        bundle and the battery, `seed` copies a feature store in, `acquire` fetches images from the\n//        collectors into a features-only shard (no image is written), `gap` says where the base\n//        is weakest and which jobs would fill it, `ingest` measures labeled local images into a\n//        new shard, `candidates` trains the weekly candidates and writes their review,\n//        `agreement` measures the north star, `battery` gates a bundle, `promote` and `rollback`\n//        are the only writers of live/, `status` says what is live.\n//  PIN:  Battery and promote run the full detector in process, one image at a time (one MLX\n//        workload); everything else is CPU work on stored features. Exit 1 on a failed battery.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct FlywheelCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"flywheel\", abstract: \"Grow the specialist heads forever: the live bundle, the features-only store, candidates, the battery, promote and rollback.\",\n        discussion: \"Run `flywheel init` once; then ingest or seed, `candidates`, review REVIEW.md, and `promote` what passes.\",\n        subcommands: [Init.self, Seed.self, Acquire.self, Gap.self, IngestImages.self, Candidates.self, AgreementCommand.self, Battery.self, Promote.self, Rollback.self, Status.self])\n\n    static func area(_ options: WorkAreaOptions) throws -> FlywheelArea { FlywheelArea(try options.resolve()) }\n\n    /// The battery as promote and rollback run it: the full detector on a bundle, the work area's spec and floors.\n    static func battery(_ area: FlywheelArea) -> Promoter.Battery {\n        { gate, root in\n            ShippedBundle.registerWeightFolders(workArea: area.area)\n            let spec = try BatterySpec.load(area.batterySpec)\n            let report = try BatteryRunner.run(spec: spec, specURL: area.batterySpec, gate: gate, baselineURL: area.batteryBaseline,\n                                               verdicts: DetectorVerdicts(bundle: try DetectorBundle.load(root)),\n                                               vars: spec.resolvedVars(images: area.batteryImages), note: note)\n            note(report.table)\n            return report\n        }\n    }\n\n    struct Init: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"init\", abstract: \"Seed <work area>/live from the shipped bundle and <work area>/battery from the shipped spec and floors.\")\n        @Flag(help: \"Only install the shipped battery spec and floors, replacing older ones (kept under battery/retired/); live/ is left alone.\")\n        var battery = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                if battery {\n                    let r = try area.replaceBattery(spec: try FlywheelResources.batterySpec(), baseline: try FlywheelResources.batteryBaseline())\n                    print(\"battery: \\(area.batterySpec.path) (spec \\(r.batterySpecSHA256.prefix(12)), floors \\(r.batteryBaselineSHA256.prefix(12)))\")\n                    print(r.retired.map { \"retired: \\($0)\" } ?? \"retired: nothing (the shipped pair was already installed)\")\n                    return\n                }\n                let report = try area.initialize(from: try ShippedBundle.verified(), spec: try FlywheelResources.batterySpec(),\n                                                 baseline: try FlywheelResources.batteryBaseline())\n                print(\"live: \\(area.live.path) (\\(report.artifacts) artifacts)\")\n                print(\"battery: \\(area.batterySpec.path) (spec \\(report.batterySpecSHA256.prefix(12)), floors \\(report.batteryBaselineSHA256.prefix(12)))\")\n            }\n        }\n    }\n\n    struct Seed: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"seed\", abstract: \"Copy a feature store's shards into <work area>/store/shards.\")\n        @Option(help: \"The store to copy from (read only).\") var from: String\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let report = try StoreSeed.copy(from: datasetURL(from), to: area.store, note: note)\n                print(\"\\(report.copied.count) shards copied (\\(report.rows) rows, \\(report.bytes / 1_000_000) MB); \\(report.kept.count) already there\")\n            }\n        }\n    }\n\n    struct Acquire: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"acquire\", abstract: \"Fetch images from the collectors into a new features-only shard; the images are measured in memory and dropped.\")\n        @Option(help: \"The day's image budget, split across the jobs (at least 50 each).\") var budget: Int = 1000\n        @Option(help: \"Images per job, overriding the budget's split.\") var per: Int?\n        @Option(help: \"gap (the last `flywheel gap`), default, test (keyless: Wikimedia and the Met), or a targets .json.\") var targets: String = \"gap\"\n        @Option(help: \"The shard's name (default: acquire_<date>).\") var shard: String?\n        @Flag(name: .customLong(\"no-route\"), help: \"Skip the CLIP router (generated images keep their job's category, NSFW is not flagged).\") var noRoute = false\n        @Flag(name: .customLong(\"dry-run\"), help: \"List the jobs and stop.\") var dryRun = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                ShippedBundle.registerWeightFolders(workArea: area.area)\n                let shipped = try AcquireTargets.shipped()\n                let gapFile = area.root.appendingPathComponent(\"acquire/targets.json\")\n                let jobs: [AcquireJob]\n                switch targets {\n                case \"test\": jobs = shipped.testJobs\n                case \"default\": jobs = shipped.defaultJobs\n                case \"gap\":\n                    if FileManager.default.fileExists(atPath: gapFile.path) { jobs = try JSONCoding.read(GapReport.self, from: gapFile).jobs }\n                    else { note(\"acquire: no gap report yet (\\(gapFile.path)); running the default jobs\"); jobs = shipped.defaultJobs }\n                case let path: jobs = try JSONCoding.read([AcquireJob].self, from: datasetURL(path))\n                }\n                let perJob = per ?? max(50, budget / max(1, jobs.count))\n                for j in jobs { note(\"  job: \\(j.source) \\(j.category)/\\(j.label) '\\(j.query.prefix(50))'\" + (j.gap.map { \" (gap \\($0))\" } ?? \"\")) }\n                if dryRun { print(\"\\(jobs.count) jobs × \\(perJob) images\"); return }\n                let live = try area.liveBundle()\n                guard let warp = live.url(.warpTile) else { throw VeilGardeFailure.missing(\"the live bundle has no warp tile model\") }\n                let router: CategoryRouter? = noRoute ? nil : try CategoryRouter()\n                if router != nil { _ = try CLIPLens.shared.tower() }\n                let report = try Acquirer(area: area, note: note).run(jobs, perJob: perJob, extractor: try FeatureExtractor(warpModelURL: warp), router: router, shard: shard)\n                for j in report.jobs {\n                    print(\"\\(j.job.source) \\(j.job.category)/\\(j.job.label): \" + (j.skipped.map { \"skipped, \\($0)\" } ?? \"\\(j.accepted) kept of \\(j.fetched) fetched, rejected \\(j.rejected)\"))\n                }\n                print(report.shard.map { \"\\($0): \\(report.rows) rows in \\(area.store.path) (\\(Int(report.seconds)) s); no image was written\" } ?? \"no rows kept\")\n            }\n        }\n    }\n\n    struct Gap: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"gap\", abstract: \"Rank the store's (domain, category, label) buckets by the base's error plus its disagreement with the pooled verdict, and write the jobs that fill the worst.\")\n        @Option(help: \"Comma-separated shards to read (default: all).\") var shards: String?\n        @Flag(name: .customLong(\"no-write\"), help: \"Print the report without writing acquire/targets.json.\") var noWrite = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let report = try GapMiner.mine(try area.liveBundle(), store: FeatureStore(directory: area.store),\n                                               shards: shards.map { $0.split(separator: \",\").map(String.init) }, targets: try AcquireTargets.shipped())\n                print(report.table)\n                if !noWrite {\n                    let out = area.root.appendingPathComponent(\"acquire/targets.json\")\n                    try JSONCoding.write(report, to: out)\n                    print(\"\\nwrote \\(report.jobs.count) jobs → \\(out.path)\")\n                } else {\n                    print(\"\\n\\(report.jobs.count) jobs (not written)\")\n                }\n            }\n        }\n    }\n\n    struct IngestImages: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"ingest\", abstract: \"Measure labeled images into a new store shard under the live warp model; the images are read and dropped.\")\n        @Argument(help: \"A .jsonl of {path, label, category, source?, golden?, gen_family?}.\") var items: String\n        @Option(help: \"The new shard's name.\") var shard: String\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                let area = try FlywheelCommand.area(workArea)\n                let list = try JSONCoding.readLines(ExtractionItem.self, from: datasetURL(items))\n                let report = try Ingest.run(list, shard: shard, area: area, note: note)\n                print(String(format: \"%@: %d rows written, %d already in the store, %d skipped, %.1fs\", report.shard, report.rows, report.skippedKnown, report.failed.count, report.seconds))\n            }\n        }\n    }\n\n    struct Candidates: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"candidates\", abstract: \"Train the weekly candidates (a warm-started base and the atlas heads) on top of live, measure them, write REVIEW.md.\")\n        @Option(help: \"The candidate's id (default: weekly-<date>).\") var id: String?\n        @Flag(name: .customLong(\"allow-mixed-warp\"), help: \"Let the base train on rows whose warp column came from different warp models.\") var allowMixedWarp = false\n        @Flag(help: \"Replace a candidate with the same id.\") var replace = false\n        @Flag(help: \"Print the plan and stop.\") var plan = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let f = DateFormatter()\n                f.locale = Locale(identifier: \"en_US_POSIX\")\n                f.dateFormat = \"yyyyMMdd\"\n                let recipe = WeeklyCandidates.recipe(id: id ?? \"weekly-\\(f.string(from: Date()))\", allowMixedWarp: allowMixedWarp)\n                if plan {\n                    let p = try TrainingEngine(area: area.area, parent: area.live, store: area.store).plan(recipe)\n                    print(p.summary)\n                    return\n                }\n                let outcome = try WeeklyCandidates.run(recipe, area: area, replace: replace) { if let line = $0.line { note(line) } }\n                print(\"candidate: \\(outcome.candidate.root.path)\")\n                print(\"review:    \\(outcome.review.path)\")\n                print(String(format: \"agreement: %.4f live → %.4f candidate; AUC gap %.4f → %.4f\", outcome.liveAgreement.agreementAll,\n                             outcome.candidateAgreement.agreementAll, outcome.liveAgreement.aucGap, outcome.candidateAgreement.aucGap))\n            }\n        }\n    }\n\n    struct AgreementCommand: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"agreement\", abstract: \"Measure the north star on the store: base ↔ pooled agreement and both AUCs, for live or a bundle.\")\n        @Option(help: \"A bundle to measure instead of live (a candidate).\") var bundle: String?\n        @Flag(name: .customLong(\"no-log\"), help: \"Do not append the row to flywheel_metrics.csv.\") var noLog = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let target = try bundle.map { try ModelBundle.load(datasetURL($0)) } ?? area.liveBundle()\n                let r = try Agreement.measure(target, store: FeatureStore(directory: area.store), label: bundle.map { URL(fileURLWithPath: $0).lastPathComponent } ?? \"live\")\n                if !noLog { try Agreement.append(r, to: area.metricsCSV) }\n                print(String(format: \"%@: %d rows (camera %d, processed %d)\", r.bundle, r.rows, r.camera, r.processed))\n                print(String(format: \"  agreement %.4f all, %@ camera, %@ processed\", r.agreementAll, r.agreementCamera.map { String(format: \"%.4f\", $0) } ?? \"n/a\",\n                             r.agreementProcessed.map { String(format: \"%.4f\", $0) } ?? \"n/a\"))\n                print(String(format: \"  test %d rows: base AUC %.4f (real FPR %.3f, gen FNR %.3f); pooled AUC %.4f (real FPR %.3f, gen FNR %.3f); gap %+.4f\",\n                             r.testRows, r.baseAUC, r.baseRealFPR, r.baseGenFNR, r.weightedAUC, r.weightedRealFPR, r.weightedGenFNR, r.aucGap))\n            }\n        }\n    }\n\n    struct Battery: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"battery\", abstract: \"Run the battery on live (or a bundle): HARD groups for --gate promote, every group for full.\")\n        @Option(help: \"promote or full.\") var gate: String = BatterySpec.Gate.full.rawValue\n        @Option(help: \"A bundle to gate instead of live (a candidate).\") var bundle: String?\n        @Option(help: \"Write the report JSON here (`-` for stdout).\") var json: String?\n        @Flag(help: \"Re-record the ratchet floors from this run (full gate only, with --yes-i-reviewed).\") var rebaseline = false\n        @Flag(name: .customLong(\"yes-i-reviewed\"), help: \"Confirms a rebaseline was reviewed.\") var reviewed = false\n        @OptionGroup var expert: BaseExpertOptions\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                guard let g = BatterySpec.Gate(rawValue: gate) else { throw VeilGardeFailure.usage(\"--gate is promote or full\") }\n                if rebaseline && !(g == .full && reviewed) { throw VeilGardeFailure.usage(\"--rebaseline needs --gate full and --yes-i-reviewed\") }\n                let base = try expert.resolve()\n                if rebaseline && base != .fusion { throw VeilGardeFailure.usage(\"--rebaseline records the detector's floors; it cannot run with --base \\(base.rawValue)\") }\n                let area = try FlywheelCommand.area(workArea)\n                ShippedBundle.registerWeightFolders(workArea: area.area)\n                let root = bundle.map(datasetURL) ?? area.live\n                let spec = try BatterySpec.load(area.batterySpec)\n                let report = try BatteryRunner.run(spec: spec, specURL: area.batterySpec, gate: g, baselineURL: area.batteryBaseline,\n                                                   verdicts: DetectorVerdicts(bundle: try DetectorBundle.load(root), baseExpert: base),\n                                                   vars: spec.resolvedVars(images: area.batteryImages), rebaseline: rebaseline, note: note)\n                let saved = area.batteryRuns.appendingPathComponent(\"\\(FlywheelArea.stamp())-\\(g.rawValue).json\")\n                try JSONCoding.write(report, to: saved)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(report.table)\n                note(\"report: \\(saved.path)\")\n                if !report.pass { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Promote: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"promote\", abstract: \"Promote one slot from a candidate into live, behind its battery; a failure restores live.\")\n        @Argument(help: \"base, combiner, calibration, or a head (art, blur, human, cgi, preview, art-pair, screenshot, semtile).\") var slot: String\n        @Option(help: \"The candidate bundle.\") var from: String\n        @Flag(name: .customLong(\"dry-run\"), help: \"Run every check and print what would change; write nothing, run no battery.\") var dryRun = false\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let s = try FlywheelSlot(parsing: slot)\n                let promoter = Promoter(area: area, battery: FlywheelCommand.battery(area), note: note)\n                if dryRun {\n                    let preview = try promoter.preview(s, from: datasetURL(from), store: FeatureStore(directory: area.store))\n                    print(\"would promote \" + preview.summary)\n                    return\n                }\n                let record = try promoter.promote(s, from: datasetURL(from), store: FeatureStore(directory: area.store))\n                print(\"promoted \\(record.slot): \\(record.fromSHA256?.prefix(12) ?? \"none\") → \\(record.toSHA256?.prefix(12) ?? \"?\") (battery PASS, snapshot \\(record.snapshot ?? \"?\"))\")\n            }\n        }\n    }\n\n    struct Rollback: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"rollback\", abstract: \"Restore live from a snapshot in live/.history (the newest by default), then run the full battery.\")\n        @Argument(help: \"The snapshot's stamp.\") var stamp: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let record = try Promoter(area: area, battery: FlywheelCommand.battery(area), note: note).rollback(to: stamp)\n                print(\"rolled back to \\(record.snapshot ?? \"?\") (battery \\(record.battery ?? \"?\"))\")\n                if record.battery != \"PASS\" { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Status: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"status\", abstract: \"What is live, what moved last, and the snapshots to roll back to.\")\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try FlywheelCommand.area(workArea)\n                let live = try area.liveBundle()\n                print(\"live: \\(live.root.path)\")\n                for a in live.manifest.artifacts { print(\"  \\(a.slot.padding(toLength: 22, withPad: \" \", startingAt: 0)) \\(a.sha256.prefix(12))  \\(a.frozen ? \"frozen \" : \"       \")\\(a.file)\") }\n                for e in live.manifest.history.suffix(5) { print(\"  \\(e.kind.rawValue) \\(e.slot) \\(e.date)\") }\n                let snapshots = Promoter(area: area, battery: { _, _ in throw VeilGardeFailure.internalError(\"status runs no battery\") }).snapshots()\n                print(\"snapshots: \\(snapshots.isEmpty ? \"none\" : snapshots.suffix(5).joined(separator: \", \"))\")\n                let shards = FeatureStore(directory: area.store).shardNames()\n                print(\"store: \\(shards.count) shards in \\(area.store.path)\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Parity.swift","status":"added","lang":"swift","hunks":[[1,0,1,161]],"header":{"lines":[1,16],"target":"VeilGardeCLI","what":[6,12],"pin":[13,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":1609,"scopes":[["S","ParityCommand",null,"",22,22,[22,38],161,null,-1,0,"a"],["f","floats",["_"],"static",27,27,[27,48],27,null,0,8,"a"],["f","report",["_","pass"],"static",29,29,[29,70],32,null,0,0,"a"],["S","Warp",null,"",34,34,[34,33],56,null,0,0,"a"],["f","run",[],"",39,39,[39,26],55,null,3,0,"a"],["f","maxDiff",["_","_"],"",45,45,[45,67],45,null,4,12,"a"],["S","Dirsig",null,"",58,58,[58,35],88,null,0,0,"a"],["f","run",[],"",63,63,[63,26],87,null,6,0,"a"],["S","Dino",null,"",90,90,[90,33],129,null,0,0,"a"],["f","run",[],"",97,97,[97,26],128,null,8,0,"a"],["f","cosine",["_","_"],"",103,103,[103,65],107,null,9,4,"a"],["S","Clip",null,"",131,131,[131,33],160,null,0,0,"a"],["f","run",[],"",136,136,[136,26],159,null,11,0,"a"],["f","cosine",["_","_"],"",144,144,[144,85],144,null,12,12,"a"]],"old":"","new":"//\n//  Parity.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde parity`: the checks against the Python references. `warp` compares one tile's\n//        residual maps with a cv2 fixture (dump_reference.py); `dirsig` compares the directional\n//        signature with a v4_a1_tilesig fixture. Each prints a JSON report of max |Δ| for the\n//        quantized and the exact-coordinate paths and exits 3 when the quantized path misses.\n//        `dino` compares DINOv2 embeddings of HF-preprocessed pixels with the dino_parity_dump.py\n//        references, isolating the ViT; with --images it runs the full Swift preprocessing on the\n//        raw images too (the end-to-end check).\n//  PIN:  Garde's --verify-warp, --verify-dirsig, --verify-dino and --verify-dino-e2e, with their\n//        thresholds: warp < 1e-3; signature < 1e-3 on the 16 raw energies and < 5e-3 on the 5\n//        log-ratios (log amplifies near-zero energies); ViT cosine ≥ 0.999; end to end ≥ 0.99.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct ParityCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"parity\", abstract: \"Check the lens against the Python fixtures and against Garde.\",\n        subcommands: [Warp.self, Dirsig.self, Dino.self, Clip.self])\n\n    static func floats(_ any: Any?) -> [Float]? { (any as? [Any])?.map { Float(($0 as? NSNumber)?.doubleValue ?? 0) } }\n\n    static func report(_ values: [String: Double], pass: Bool) throws {\n        try emitJSON(try JSONSerialization.data(withJSONObject: values, options: [.sortedKeys]), to: \"-\")\n        if !pass { throw ArgumentParser.ExitCode(FailureCode.parityMismatch.rawValue) }\n    }\n\n    struct Warp: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"warp\", abstract: \"Compare one tile's warp residual maps with a cv2 fixture ({tile, R_low, R_high}).\")\n\n        @Argument(help: \"The fixture JSON.\") var fixture: String\n\n        func run() throws {\n            guarded {\n                let object = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: fixture))) as? [String: Any]\n                guard let tile = ParityCommand.floats(object?[\"tile\"]), let low = ParityCommand.floats(object?[\"R_low\"]), let high = ParityCommand.floats(object?[\"R_high\"]) else {\n                    throw VeilGardeFailure.data(\"\\(fixture) is not a warp fixture ({tile, R_low, R_high})\")\n                }\n                func maxDiff(_ a: [Float], _ b: [Float]) -> Double { Double(zip(a, b).map { abs($0 - $1) }.max() ?? .infinity) }\n                var report = [String: Double]()\n                for quantize in [true, false] {\n                    let maps = WarpDebug.residualMaps(tileRGB: tile, quantizeLikeCV2: quantize)\n                    let key = quantize ? \"cv2_quantized\" : \"exact_double\"\n                    report[\"\\(key)_low_maxdiff\"] = maxDiff(maps.low, low)\n                    report[\"\\(key)_high_maxdiff\"] = maxDiff(maps.high, high)\n                }\n                try ParityCommand.report(report, pass: (report[\"cv2_quantized_low_maxdiff\"] ?? 1) < 1e-3 && (report[\"cv2_quantized_high_maxdiff\"] ?? 1) < 1e-3)\n            }\n        }\n    }\n\n    struct Dirsig: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"dirsig\", abstract: \"Compare the directional signature with a v4_a1_tilesig fixture ({height, width, image, sig}).\")\n\n        @Argument(help: \"The fixture JSON.\") var fixture: String\n\n        func run() throws {\n            guarded {\n                let object = try JSONSerialization.jsonObject(with: Data(contentsOf: URL(fileURLWithPath: fixture))) as? [String: Any]\n                guard let h = (object?[\"height\"] as? NSNumber)?.intValue, let w = (object?[\"width\"] as? NSNumber)?.intValue,\n                      let img = ParityCommand.floats(object?[\"image\"]), let sig = ParityCommand.floats(object?[\"sig\"]) else {\n                    throw VeilGardeFailure.data(\"\\(fixture) is not a signature fixture ({height, width, image, sig})\")\n                }\n                let tiles = (h / 32) * (w / 32)\n                var report = [String: Double]()\n                for quantize in [true, false] {\n                    let got = WarpDebug.directionalSignature(imageRGB: img, height: h, width: w, quantizeLikeCV2: quantize)\n                    var raw: Float = 0, derived: Float = 0\n                    for t in 0..<tiles {\n                        for f in 0..<DirectionalSignature.count {\n                            let d = abs(got[t * 21 + f] - sig[t * 21 + f])\n                            if f < 16 { raw = max(raw, d) } else { derived = max(derived, d) }\n                        }\n                    }\n                    let key = quantize ? \"cv2_quantized\" : \"exact_double\"\n                    report[\"\\(key)_raw_maxdiff\"] = Double(raw)\n                    report[\"\\(key)_derived_maxdiff\"] = Double(derived)\n                }\n                try ParityCommand.report(report, pass: (report[\"cv2_quantized_raw_maxdiff\"] ?? 1) < 1e-3 && (report[\"cv2_quantized_derived_maxdiff\"] ?? 1) < 5e-3)\n            }\n        }\n    }\n\n    struct Dino: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"dino\", abstract: \"Compare DINOv2 embeddings with the dino_parity_dump.py references (<name>.pixels, <name>.emb).\")\n\n        @Argument(help: \"The fixture safetensors.\") var fixture: String\n        @Option(help: \"The raw images' folder, for the end-to-end check (bahamut.jpg, test1.png, IMG_4096.jpeg).\") var images: String?\n        @Option(help: \"DINOv2 weights: small, xsmall or xxsmall.\") var dino: String = DinoVariant.small.rawValue\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino must be small, xsmall or xxsmall\") }\n                let file = try SafetensorsFile(url: URL(fileURLWithPath: (fixture as NSString).expandingTildeInPath))\n                let bases = Set(file.names.filter { $0.hasSuffix(\".pixels\") }.map { String($0.dropLast(\".pixels\".count)) }).sorted()\n                func cosine(_ a: [Float], _ b: [Float]) -> Float {\n                    var dot: Float = 0, na: Float = 0, nb: Float = 0\n                    for i in 0..<min(a.count, b.count) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i] }\n                    return dot / (na.squareRoot() * nb.squareRoot())\n                }\n                var allPass = true\n                for base in bases {\n                    let pixels = try file.float32(\"\\(base).pixels\"), reference = try file.float32(\"\\(base).emb\")\n                    let cos = cosine(try SemanticLens.embedding(pixels: pixels, variant: variant), reference)\n                    let pass = cos >= 0.999\n                    allPass = allPass && pass\n                    print(base.padding(toLength: 12, withPad: \" \", startingAt: 0) + String(format: \" vit cosine %.5f  \", cos) + (pass ? \"PASS\" : \"FAIL\"))\n                }\n                if let images {\n                    for (base, name) in [(\"bahamut\", \"bahamut.jpg\"), (\"test1\", \"test1.png\"), (\"IMG_4096\", \"IMG_4096.jpeg\")] {\n                        let url = URL(fileURLWithPath: (images as NSString).expandingTildeInPath).appendingPathComponent(name)\n                        guard let reference = try? file.float32(\"\\(base).emb\"), let cg = try? ImageDecoding.cgImage(contentsOf: url) else { print(\"\\(base): missing\"); continue }\n                        let cos = cosine(try SemanticLens.fusionEmbedding(cg, variant: variant), reference)\n                        let pass = cos >= 0.99\n                        allPass = allPass && pass\n                        print(base.padding(toLength: 12, withPad: \" \", startingAt: 0) + String(format: \" e2e cosine %.5f  \", cos) + (pass ? \"PASS\" : \"FAIL\"))\n                    }\n                }\n                if !allPass { throw ArgumentParser.ExitCode(FailureCode.parityMismatch.rawValue) }\n            }\n        }\n    }\n\n    struct Clip: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"clip\", abstract: \"The CLIP vision tower against Hugging Face's embeddings on the same pixels (clip_parity.safetensors).\")\n        @Argument(help: \"The fixture (default: Tests/VeilGardeLensTests/Fixtures/clip_parity.safetensors).\") var fixture: String?\n        @Option(help: \"The image files the fixture's first rows came from, to also check the Swift preprocessing end to end.\") var images: [String] = []\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                let url = fixture.map(datasetURL) ?? URL(fileURLWithPath: \"Tests/VeilGardeLensTests/Fixtures/clip_parity.safetensors\")\n                let f = try SafetensorsFile(url: url)\n                let pixels = try f.uint8(\"pixels\"), expected = try f.float32(\"embeds\")\n                let n = try f.tensor(\"pixels\").shape[0]\n                let ours = try CLIPLens.shared.tower()(CLIPPreprocess.input(pixels: pixels, count: n)).asArray(Float.self)\n                func cosine(_ a: ArraySlice<Float>, _ b: ArraySlice<Float>) -> Float { zip(a, b).reduce(Float(0)) { $0 + $1.0 * $1.1 } }\n                var worst: Float = 1\n                for i in 0..<n {\n                    let c = cosine(ours[(i * 512)..<((i + 1) * 512)], expected[(i * 512)..<((i + 1) * 512)])\n                    worst = min(worst, c)\n                    print(String(format: \"image %d: cosine %.7f (same pixels)\", i, c))\n                }\n                for (i, path) in images.enumerated() where i < n {\n                    let e = try CLIPLens.embedding(try loadImage(path))\n                    print(String(format: \"%@: cosine %.5f (decoded and preprocessed here, HF's PIL resize there)\", (path as NSString).lastPathComponent,\n                                 cosine(e[0..<512], expected[(i * 512)..<((i + 1) * 512)])))\n                }\n                print(String(format: \"worst cosine on the same pixels: %.7f %@\", worst, worst >= 0.999 ? \"(≥ 0.999)\" : \"(below 0.999)\"))\n                if worst < 0.999 { throw ExitCode(1) }\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Research.swift","status":"added","lang":"swift","hunks":[[1,0,1,306]],"header":{"lines":[1,16],"target":"VeilGardeCLI","what":[6,11],"pin":[12,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":1623,"scopes":[["S","ResearchCommand",null,"",22,22,[22,40],182,null,-1,0,"a"],["f","output",["_","_"],"static",27,27,[27,71],31,null,0,0,"a"],["S","Prune",null,"",33,33,[33,34],107,null,0,0,"a"],["f","run",[],"",46,46,[46,26],67,null,2,0,"a"],["f","table",["_"],"static",69,69,[69,56],106,null,2,0,"a"],["f","pad",["_","_"],"",71,71,[71,54],71,null,4,12,"a"],["f","section",["_","_"],"",72,72,[72,64],82,null,4,4,"a"],["S","Census",null,"",109,109,[109,35],181,null,0,0,"a"],["f","run",[],"",124,124,[124,26],180,null,7,0,"a"],["S","MechanismCensus",null,"",185,185,[185,32],306,[184,184],-1,0,"a"],["S","Row",null,"",186,186,[186,24],210,null,9,0,"a"],["f","add",["_","label","_","domain"],"mutating",244,244,[244,92],275,null,9,0,"a"],["f","counted",["_","_","_"],"static",277,277,[277,119],281,null,9,0,"a"],["v","table",null,"",283,283,[283,22],305,null,9,0,"a"]],"old":"","new":"//\n//  Research.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research`: measurements that ask what the system could do without. `prune`\n//        runs the pruning study (PruningStudy) on the work area's tile cache and store against the\n//        shipped bundle; `core` refits the warp tile model on feature subsets (CoreStudy,\n//        ResearchCore.swift); `census` runs the full detector over images (the battery's, a final_mixed\n//        sample, or any given) and counts how often each mechanism and stack row runs, how often it\n//        decides the call, and how often the stack and the semantic chain move it.\n//  PIN:  prune is CPU work on cached tiles and stored features; census is one MLX workload, one\n//        image at a time. Each writes <work area>/research/<what>-<stamp>.json and prints a table.\n//        A census names the bundle and the base expert it ran, and per image the sensor call and\n//        the warp lens's own score beside the routed verdict (fields older censuses lack).\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct ResearchCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"research\", abstract: \"Measure what the system could do without: the pruning study and the mechanism census.\",\n        subcommands: [Prune.self, Core.self, Redundancy.self, Condensed.self, Census.self, Compare.self])\n\n    static func output(_ area: WorkArea, _ what: String) throws -> URL {\n        let folder = area.root.appendingPathComponent(\"research\", isDirectory: true)\n        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)\n        return folder.appendingPathComponent(\"\\(what)-\\(FlywheelArea.stamp()).json\")\n    }\n\n    struct Prune: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"prune\", abstract: \"Refit and re-score the warp model, the fusion head and the stack with parts taken out, on held-out data.\",\n            discussion: \"The rules are fixed in the report (ledger decision-68). The warp part refits the deployed shape about 30 times on the tile cache; the fusion part refits the scratch recipe 8 times on the store.\")\n        @Option(help: \"The parts to study: warp, fusion, stack, comma separated.\") var parts = \"warp,fusion,stack\"\n        @Option(help: \"Bootstrap resamples per comparison.\") var resamples = 1000\n        @Option(help: \"The warp tile cache (default: <work area>/store/tiles/final_mixed).\") var tiles: String?\n        @Option(help: \"The feature store (default: <work area>/store/shards).\") var store: String?\n        @Flag(name: .customLong(\"no-single-features\"), help: \"Skip the 19 single-feature refits.\") var noSingleFeatures = false\n        @Option(help: \"Fusion trees for the scratch refits.\") var fusionTrees = 500\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                var settings = PruningSettings()\n                settings.resamples = resamples\n                settings.singleFeatures = !noSingleFeatures\n                settings.fusionTrees = fusionTrees\n                settings.fusionStages = settings.fusionStages.filter { $0 < fusionTrees }\n                let chosen = try Set(parts.split(separator: \",\").map { name -> PruningPart in\n                    guard let p = PruningPart(rawValue: name.trimmingCharacters(in: .whitespaces)) else { throw VeilGardeFailure.usage(\"--parts names warp, fusion and stack, not \\(name)\") }\n                    return p\n                })\n                let inputs = PruningStudy.Inputs(tiles: tiles.map(datasetURL) ?? area.tiles.appendingPathComponent(\"final_mixed\", isDirectory: true),\n                                                 store: store.map(datasetURL) ?? area.shards, bundle: try ShippedBundle.verified())\n                let report = try PruningStudy.run(inputs, settings: settings, parts: chosen, note: note)\n                let file = try ResearchCommand.output(area, \"prune\")\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path)\")\n            }\n        }\n\n        static func table(_ r: PruningReport) -> String {\n            var lines: [String] = []\n            func pad(_ s: String, _ n: Int) -> String { s.count >= n ? s : s + String(repeating: \" \", count: n - s.count) }\n            func section(_ title: String, _ rows: [PruningRow]) {\n                guard !rows.isEmpty else { return }\n                lines.append(title)\n                for row in rows {\n                    let p = row.primary\n                    var line = \"  \" + pad(row.name, 30) + String(format: \" %+.4f [%+.4f, %+.4f]\", p.delta, p.low, p.high)\n                    if let s = row.secondary { line += String(format: \"  vote %+.4f\", s.delta) }\n                    line += \"  moved \\(p.changedCalls)  \\(row.verdict)\"\n                    lines.append(line)\n                }\n            }\n            if let w = r.warp {\n                lines.append(String(format: \"warp: refit deployed shape, test weighted AUC %.4f, vote AUC %.4f (%d images); shipped %.4f / %.4f on its own corpus\",\n                                    w.reference.imageWeightedAUC, w.reference.imageMajorityAUC, w.testImages, w.shipped.imageWeightedAUC, w.shipped.imageMajorityAUC))\n                section(\" the control: another seed\", w.seeds)\n                section(\" trees\", w.trees); section(\" depth\", w.depths); section(\" a group shuffled\", w.permuted); section(\" a group refit out\", w.groupsDropped)\n                section(\" groups refit out together\", w.groupsTogether)\n                section(\" a feature refit out\", w.featuresDropped); section(\" together\", w.droppedTogether.map { [$0] } ?? []); section(\" other image scores\", w.scores)\n                section(\" shipped, trees\", w.shippedTrees); section(\" shipped, a group shuffled\", w.shippedPermuted)\n                let c = w.calibration\n                lines.append(String(format: \" calibration: the call is a raw tile-vote cut on %d of %d images (real ≤ %.4f, generated ≥ %.4f)\", c.agreeing, c.images, c.rawReal, c.rawGenerated))\n            }\n            if let f = r.fusion {\n                lines.append(String(format: \"fusion: scratch recipe on all inputs, AUC %.4f on %d held-out rows; shipped %.4f (reliance)\", f.referenceAUC, f.testRows, f.shippedAUC))\n                section(\" the control: another seed\", f.seeds)\n                section(\" trees\", f.trees); section(\" depth\", f.depths); section(\" inputs\", f.inputs); section(\" inputs together\", f.inputsTogether)\n                section(\" shipped, trees\", f.shippedTrees); section(\" shipped, an input shuffled\", f.shippedPermuted)\n            }\n            if let s = r.stack {\n                lines.append(String(format: \"stack: %d capture-absent rows, AUC %.4f, real FPR %.3f, generated recall %.3f; live: %@\",\n                                    s.rows, s.shippedAUC, s.shippedRealFPR, s.shippedGeneratedRecall, s.active.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")))\n                section(\" a term or head out\", s.variants)\n            }\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n\n    struct Census: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"census\", abstract: \"Run the full detector over images and count how often each mechanism runs and decides the call.\",\n            discussion: \"With no images it takes the battery's (every group) and a final_mixed sample. One MLX workload, one image at a time.\")\n        @Argument(help: \"Images, folders (searched recursively), or text files of image paths (one per line).\") var images: [String] = []\n        @Option(help: \"The label of the images named as arguments: real or generated.\") var label: String?\n        @Option(help: \"A bundle directory to detect with instead of the shipped one (live, or a candidate).\") var bundle: String?\n        @OptionGroup var expert: BaseExpertOptions\n        @Flag(help: \"Add the battery's images (every group of the work area's spec).\") var battery = false\n        @Option(help: \"Add this many final_mixed images, half real and half generated, every k-th by name.\") var sample = 0\n        @Option(name: .customLong(\"final-mixed\"), help: \"The final_mixed folder (default: final_mixed under VEILGARDE_DATASETS, else the work area's datasets/).\") var finalMixed: String?\n        @Option(help: \"Write the census here too (`-` for stdout).\") var json: String?\n        @OptionGroup var route: DetectionOptions\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                if let label, ![\"real\", \"generated\"].contains(label) { throw VeilGardeFailure.usage(\"--label is real or generated, not \\(label)\") }\n                var items: [(path: String, label: String?)] = []\n                for input in images { items += try imageInputs(input).map { ($0.path, label) } }\n                let defaults = images.isEmpty && !battery && sample == 0\n                if battery || defaults {\n                    let fly = FlywheelArea(area)\n                    let spec = try BatterySpec.load(fly.batterySpec)\n                    for group in try spec.resolve(gate: .full, vars: spec.resolvedVars(images: fly.batteryImages)) {\n                        items += group.files.map { ($0, group.want) }\n                    }\n                }\n                let count = defaults ? 200 : sample\n                if count > 0 {\n                    guard let finalMixed = finalMixed.map(datasetURL) ?? WorkArea.datasets().map({ $0.appendingPathComponent(\"final_mixed\") }) else {\n                        throw VeilGardeFailure.usage(\"no final_mixed: pass --final-mixed or set VEILGARDE_DATASETS\")\n                    }\n                    for label in [\"real\", \"generated\"] {\n                        let folder = finalMixed.appendingPathComponent(label)\n                        let names = ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])\n                            .filter { !$0.hasPrefix(\".\") && [\"jpg\", \"jpeg\", \"png\", \"webp\", \"heic\"].contains(URL(fileURLWithPath: $0).pathExtension.lowercased()) }.sorted()\n                        let k = max(1, names.count / max(1, count / 2))\n                        items += stride(from: 0, to: names.count, by: k).prefix(count / 2).map { (folder.appendingPathComponent(names[$0]).path, label) }\n                    }\n                }\n                guard !items.isEmpty else { throw VeilGardeFailure.usage(\"no images: name some, or pass --battery or --sample\") }\n                var config = try bundle.map { try route.config(bundle: try DetectorBundle.load(datasetURL($0))) } ?? route.config()\n                config.baseExpert = try expert.resolve()\n                var census = MechanismCensus()\n                census.bundle = config.bundle.directory.path\n                census.provenance = config.bundle.provenance\n                census.baseExpert = config.baseExpert.rawValue\n                census.warpRule = config.decision\n                census.weightsDir = route.weightsDir\n                census.modelOverride = route.model\n                census.dinoVariant = config.dinoVariant.rawValue\n                census.coreVersion = VeilGardeVersion.string\n                for (k, item) in items.enumerated() {\n                    defer { LensRuntime.releaseMemory() }\n                    do {\n                        let cg = try loadImage(item.path)\n                        let routed = try Detector.shared.detect(cgImage: cg, config: config)\n                        census.add(item.path, label: item.label, routed.result, domain: routed.domain.rawValue)\n                    } catch {\n                        census.errors.append(\"\\(item.path): \\(error)\")\n                    }\n                    if (k + 1) % 25 == 0 { note(\"census: \\(k + 1) of \\(items.count) images\") }\n                }\n                let file = try ResearchCommand.output(area, \"census\")\n                try JSONCoding.write(census, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(census), to: json) }\n                print(census.table)\n                note(\"census: \\(file.path)\")\n            }\n        }\n    }\n}\n\n/// How often each part of the router ran on a set of images, and how often it decided.\nstruct MechanismCensus: Codable {\n    struct Row: Codable {\n        var path: String\n        var label: String?\n        var route: String\n        var capture: String\n        var baseP: Float?\n        var preSemanticP: Float?\n        var p: Float\n        var call: String\n        var preSemanticCall: String?\n        var shown: [String]\n        var decisive: [String]\n        var semanticTriggered: Bool\n        var semanticDecisive: Bool\n        var previewTriggered: Bool\n        var previewDecisive: Bool\n        /// The camera-sensor call and its vote (the majority route), nil off the camera route.\n        var sensorP: Float? = nil\n        var sensorCall: String? = nil\n        /// The warp lens's own weighted score and its call at the warp rule, whatever the base expert.\n        var warpP: Float? = nil\n        var warpCall: String? = nil\n        /// The base expert's own call (the first stack row).\n        var baseCall: String? = nil\n    }\n\n    var date = Date()\n    /// What ran: the bundle, its artifacts' hashes, the base expert and the overrides.\n    var bundle: String? = nil\n    var provenance: [String: String]? = nil\n    var baseExpert: String? = nil\n    var warpRule: DecisionRule? = nil\n    var weightsDir: String? = nil\n    var modelOverride: String? = nil\n    var dinoVariant: String? = nil\n    var coreVersion: String? = nil\n    var rows: [Row] = []\n    var errors: [String] = []\n    var routes: [String: Int] = [:]\n    var capture: [String: Int] = [:]\n    /// Stack rows by name: how many images showed each.\n    var shown: [String: Int] = [:]\n    /// Stack rows at full weight (the part that decided or moved the call), by name, then by label.\n    var decisive: [String: [String: Int]] = [:]\n    /// Capture-absent images whose pre-semantic call differs from the fusion base's call at 0.5.\n    var stackMovedCall = 0\n    /// Images whose final call differs from the pre-semantic one.\n    var semanticMovedCall = 0\n    /// The final call against the label, where the label is known.\n    var correct: [String: Int] = [:]\n    var labelled: [String: Int] = [:]\n    /// By label (\"unlabelled\" when unknown), then call: the sensor's, the routed verdict's, the warp lens's own.\n    var sensorCalls: [String: [String: Int]]? = nil\n    var finalCalls: [String: [String: Int]]? = nil\n    var warpCalls: [String: [String: Int]]? = nil\n    /// The warp lens's own call against the label.\n    var warpCorrect: [String: Int]? = nil\n\n    mutating func add(_ path: String, label: String?, _ r: InferenceResult, domain: String) {\n        let cap = r.captureSignature.map { $0.valid ? ($0.present ? \"present\" : \"absent\") : \"invalid\" } ?? \"none\"\n        let d = r.routeDiagnostics\n        let stack = r.specialists ?? []\n        var row = Row(path: path, label: label, route: domain, capture: cap, baseP: d?.warpP, preSemanticP: d?.preSemanticP, p: r.weightedScore,\n                      call: r.weightedPrediction, preSemanticCall: d?.preSemanticPrediction, shown: stack.map(\\.name),\n                      decisive: stack.filter { $0.weight >= 1 }.map(\\.name), semanticTriggered: d?.semanticTriggered ?? false,\n                      semanticDecisive: d?.semanticDecisive ?? false, previewTriggered: d?.previewTriggered ?? false, previewDecisive: d?.previewDecisive ?? false)\n        row.sensorP = r.sensorRawProbability\n        row.sensorCall = r.sensorPrediction\n        row.warpP = r.warpWeightedScore\n        row.warpCall = r.warpWeightedScore.map { (warpRule ?? .warpWeighted).label($0) }\n        row.baseCall = stack.first?.verdict\n        rows.append(row)\n        let key = label ?? \"unlabelled\"\n        if let s = row.sensorCall { sensorCalls = Self.counted(sensorCalls, key, s) }\n        finalCalls = Self.counted(finalCalls, key, row.call)\n        if let w = row.warpCall {\n            warpCalls = Self.counted(warpCalls, key, w)\n            if let label { warpCorrect = (warpCorrect ?? [:]).merging([label: w == label ? 1 : 0], uniquingKeysWith: +) }\n        }\n        routes[domain, default: 0] += 1\n        capture[cap, default: 0] += 1\n        for name in Set(row.shown) { shown[name, default: 0] += 1 }\n        for name in Set(row.decisive) { decisive[name, default: [:]][label ?? \"unlabelled\", default: 0] += 1 }\n        if cap != \"present\", let base = d?.warpP, let pre = d?.preSemanticPrediction, (base > 0.5 ? \"generated\" : \"real\") != pre { stackMovedCall += 1 }\n        if let pre = d?.preSemanticPrediction, pre != r.weightedPrediction { semanticMovedCall += 1 }\n        if let label {\n            labelled[label, default: 0] += 1\n            if r.weightedPrediction == label { correct[label, default: 0] += 1 }\n        }\n    }\n\n    static func counted(_ table: [String: [String: Int]]?, _ label: String, _ call: String) -> [String: [String: Int]] {\n        var t = table ?? [:]\n        t[label, default: [:]][call, default: 0] += 1\n        return t\n    }\n\n    var table: String {\n        var lines = [\"census: \\(rows.count) images (\\(errors.count) errors); routes \" + routes.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")\n                     + \"; capture \" + capture.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")]\n        if let bundle { lines.append(\"bundle \\(bundle), base \\(baseExpert ?? \"fusion\")\" + (modelOverride.map { \", base warp model \\($0)\" } ?? \"\")) }\n        lines.append(\"  stack row                shown  full weight (by label)\")\n        for (name, n) in shown.sorted(by: { $0.value > $1.value }) {\n            let by = (decisive[name] ?? [:]).sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")\n            let label = name.count >= 24 ? name : name + String(repeating: \" \", count: 24 - name.count)\n            lines.append(\"  \" + label + String(format: \" %5d  \", n) + (by.isEmpty ? \"—\" : by))\n        }\n        lines.append(\"the stack moved the base's call on \\(stackMovedCall) capture-absent images; the semantic chain moved the call on \\(semanticMovedCall)\")\n        lines.append(\"correct: \" + labelled.sorted { $0.key < $1.key }.map { \"\\($0.key) \\(correct[$0.key] ?? 0) of \\($0.value)\" }.joined(separator: \", \"))\n        if let warpCorrect {\n            lines.append(\"the warp lens's own call correct: \" + labelled.sorted { $0.key < $1.key }.map { \"\\($0.key) \\(warpCorrect[$0.key] ?? 0) of \\($0.value)\" }.joined(separator: \", \"))\n        }\n        for (title, table) in [(\"sensor calls\", sensorCalls), (\"routed calls\", finalCalls)] {\n            guard let table else { continue }\n            lines.append(\"\\(title): \" + table.sorted { $0.key < $1.key }.map { label, calls in\n                \"\\(label) \" + [\"real\", \"inconclusive\", \"generated\"].map { \"\\($0) \\(calls[$0] ?? 0)\" }.joined(separator: \" / \")\n            }.joined(separator: \"; \"))\n        }\n        return lines.joined(separator: \"\\n\")\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/ResearchCompare.swift","status":"added","lang":"swift","hunks":[[1,0,1,201]],"header":{"lines":[1,15],"target":"VeilGardeCLI","what":[6,10],"pin":[11,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1637,"scopes":[["S","DetectorAblationRules",null,"",22,22,[22,38],35,[21,21],-1,0,"a"],["v","text",null,"",27,27,[27,23],34,null,0,0,"a"],["S","CompareSide",null,"",37,37,[37,28],53,null,-1,0,"a"],["S","CompareReport",null,"",55,55,[55,30],76,null,-1,0,"a"],["X","ResearchCommand",null,"",78,78,[78,26],201,null,-1,0,"a"],["S","Compare",null,"",79,79,[79,36],200,null,4,0,"a"],["f","run",[],"",93,93,[93,26],105,null,5,0,"a"],["f","load",["_"],"static",107,107,[107,67],107,null,5,8,"a"],["f","side",["_","path","iphone","iphonePath"],"static",109,109,[109,128],123,null,5,0,"a"],["f","share",["_"],"",116,116,[116,44],116,null,8,12,"a"],["f","compare",["name","judge","reference","variant","referenceIPhone","variantIPhone","battery","rules"],"static",125,125,[126,100],183,null,5,0,"a"],["f","table",["_"],"static",185,185,[185,56],199,null,5,0,"a"],["f","fm",["_"],"",186,186,[186,48],190,null,11,4,"a"]],"old":"","new":"//\n//  ResearchCompare.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research compare`: the detector matrix's judge. A variant's census beside the\n//        reference's, image by image: correct calls by label, the calls the variant moved to the\n//        right label and to the wrong one, the sensor call's agreement, the iPhone originals'\n//        sensor and routed real shares, and the battery's verdict, read against the rules fixed\n//        before the matrix ran (DetectorAblationRules).\n//  PIN:  Reads only the JSONs `research census` and `flywheel battery` wrote, joined by image path.\n//        R2's labelled images are the census rows under a final_mixed folder (200 in the default\n//        census); the iPhone originals are the second census of each side. Writes\n//        <work area>/research/compare-<name>-<stamp>.json.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\n/// The detector matrix's rules, as fixed before it ran (ledger decision-99).\nstruct DetectorAblationRules: Codable {\n    var maxCorrectLoss = 2\n    var minSensorAgreement = 0.98\n    var maxRealShareDrop = 0.02\n\n    var text: [String] {\n        [\n            \"R1. The full battery decides PASS or FAIL with its recorded floors.\",\n            \"R2. A part is not necessary only when the battery passes without it, the labelled final_mixed census images lose at most \\(maxCorrectLoss) correct calls against the same warp model with the part (inconclusive counts as wrong), and the changed calls moved to the wrong label are no more than those moved to the right one.\",\n            String(format: \"R3. The golden warp holds up when its cell passes the battery, its sensor call agrees with the shipped model's on at least %.0f%% of the census and iPhone images, its iPhone sensor and routed real shares are each no more than %.0f points under the shipped model's, and R2's correct-call bar holds.\", minSensorAgreement * 100, maxRealShareDrop * 100),\n            \"R4. Every cell runs and is reported whatever an earlier one did; the iPhone originals are partly the warp models' training images.\",\n        ]\n    }\n}\n\nstruct CompareSide: Codable {\n    var census: String\n    var iphone: String?\n    var provenance: [String: String]?\n    var baseExpert: String?\n    /// Labelled final_mixed images called right, by label, and their total.\n    var finalMixedCorrect: [String: Int]\n    var finalMixedImages: Int\n    /// Every labelled census image called right, and their total.\n    var labelledCorrect: Int\n    var labelledImages: Int\n    /// The warp lens's own call, right, on the same labelled images (nil for an older census).\n    var warpCorrect: Int?\n    var iphoneImages: Int?\n    var iphoneSensorReal: Double?\n    var iphoneRoutedReal: Double?\n}\n\nstruct CompareReport: Codable {\n    var date: Date\n    var name: String\n    var judge: String\n    var rules: [String]\n    var reference: CompareSide\n    var variant: CompareSide\n    var joined: Int\n    var unmatched: Int\n    /// Labelled images whose routed call moved, and where it moved.\n    var moved: Int\n    var movedToRight: Int\n    var movedToWrong: Int\n    /// The sensor call compared on images both censuses carry it for (census and iPhone together).\n    var sensorCompared: Int\n    var sensorAgreement: Double?\n    var battery: String?\n    var batteryPass: Bool?\n    var batteryStatuses: [String: String]?\n    var verdict: String\n    var reasons: [String]\n}\n\nextension ResearchCommand {\n    struct Compare: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"compare\", abstract: \"Judge a detector variant against a reference from their censuses and battery report, by the matrix's rules.\",\n            discussion: \"--judge part applies R2 (is the part taken out necessary); --judge warp applies R3 (does a warp model hold up); --judge none only measures.\")\n        @Option(help: \"The reference's census JSON.\") var reference: String\n        @Option(help: \"The variant's census JSON.\") var variant: String\n        @Option(name: .customLong(\"reference-iphone\"), help: \"The reference's census of the iPhone originals.\") var referenceIPhone: String?\n        @Option(name: .customLong(\"variant-iphone\"), help: \"The variant's census of the iPhone originals.\") var variantIPhone: String?\n        @Option(help: \"The variant's battery report JSON.\") var battery: String?\n        @Option(help: \"part, warp or none.\") var judge: String = \"none\"\n        @Option(help: \"A name for the variant in the report.\") var name: String = \"variant\"\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                guard [\"part\", \"warp\", \"none\"].contains(judge) else { throw VeilGardeFailure.usage(\"--judge is part, warp or none, not \\(judge)\") }\n                let area = try workArea.resolve()\n                let report = try Self.compare(name: name, judge: judge, reference: reference, variant: variant, referenceIPhone: referenceIPhone,\n                                              variantIPhone: variantIPhone, battery: battery, rules: DetectorAblationRules())\n                let file = try ResearchCommand.output(area, \"compare-\\(name)\")\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path)\")\n            }\n        }\n\n        static func load(_ path: String) throws -> MechanismCensus { try JSONCoding.read(MechanismCensus.self, from: datasetURL(path)) }\n\n        static func side(_ census: MechanismCensus, path: String, iphone: MechanismCensus?, iphonePath: String?) -> CompareSide {\n            let labelled = census.rows.filter { $0.label != nil }\n            let finalMixed = labelled.filter { $0.path.contains(\"/final_mixed/\") }\n            var byLabel: [String: Int] = [:]\n            for row in finalMixed where row.call == row.label { byLabel[row.label!, default: 0] += 1 }\n            let warpKnown = labelled.allSatisfy { $0.warpCall != nil } && !labelled.isEmpty\n            let iphoneRows = iphone?.rows ?? []\n            func share(_ n: Int) -> Double? { iphoneRows.isEmpty ? nil : Double(n) / Double(iphoneRows.count) }\n            return CompareSide(census: datasetURL(path).path, iphone: iphonePath.map { datasetURL($0).path }, provenance: census.provenance, baseExpert: census.baseExpert,\n                               finalMixedCorrect: byLabel, finalMixedImages: finalMixed.count, labelledCorrect: labelled.filter { $0.call == $0.label }.count,\n                               labelledImages: labelled.count, warpCorrect: warpKnown ? labelled.filter { $0.warpCall == $0.label }.count : nil,\n                               iphoneImages: iphone.map { _ in iphoneRows.count },\n                               iphoneSensorReal: share(iphoneRows.filter { $0.sensorCall == \"real\" }.count),\n                               iphoneRoutedReal: share(iphoneRows.filter { $0.call == \"real\" }.count))\n        }\n\n        static func compare(name: String, judge: String, reference: String, variant: String, referenceIPhone: String?, variantIPhone: String?,\n                            battery: String?, rules: DetectorAblationRules) throws -> CompareReport {\n            let ref = try load(reference), v = try load(variant)\n            let refI = try referenceIPhone.map(load), vI = try variantIPhone.map(load)\n            let a = side(ref, path: reference, iphone: refI, iphonePath: referenceIPhone)\n            let b = side(v, path: variant, iphone: vI, iphonePath: variantIPhone)\n            let byPath = Dictionary(v.rows.map { ($0.path, $0) }, uniquingKeysWith: { first, _ in first })\n            var joined = 0, unmatched = 0, moved = 0, right = 0, wrong = 0\n            for row in ref.rows {\n                guard let other = byPath[row.path] else { unmatched += 1; continue }\n                joined += 1\n                guard let label = row.label, row.call != other.call else { continue }\n                moved += 1\n                if other.call == label { right += 1 } else { wrong += 1 }\n            }\n            var compared = 0, agreeing = 0\n            for (x, y) in [(ref, v)] + (refI.flatMap { ri in vI.map { [(ri, $0)] } } ?? []) {\n                let other = Dictionary(y.rows.map { ($0.path, $0) }, uniquingKeysWith: { first, _ in first })\n                for row in x.rows {\n                    guard let s = row.sensorCall, let t = other[row.path]?.sensorCall else { continue }\n                    compared += 1\n                    if s == t { agreeing += 1 }\n                }\n            }\n            var pass: Bool? = nil, statuses: [String: String]? = nil\n            if let battery {\n                let object = try JSONSerialization.jsonObject(with: Data(contentsOf: datasetURL(battery))) as? [String: Any]\n                pass = object?[\"pass\"] as? Bool\n                // The battery report lists its statuses as [{group, status, floor}].\n                if let list = object?[\"statuses\"] as? [[String: Any]] {\n                    statuses = Dictionary(list.compactMap { s in (s[\"group\"] as? String).map { ($0, \"\\(s[\"status\"] ?? \"\")\") } }, uniquingKeysWith: { first, _ in first })\n                }\n            }\n            let agreement = compared > 0 ? Double(agreeing) / Double(compared) : nil\n            let loss = a.finalMixedCorrect.values.reduce(0, +) - b.finalMixedCorrect.values.reduce(0, +)\n            var reasons: [String] = []\n            var verdict = \"measured\"\n            switch judge {\n            case \"part\":\n                if pass != true { reasons.append(\"the battery does not pass without it (\\(pass.map { $0 ? \"PASS\" : \"FAIL\" } ?? \"no report\"))\") }\n                if loss > rules.maxCorrectLoss { reasons.append(\"the labelled final_mixed images lose \\(loss) correct calls (bar \\(rules.maxCorrectLoss))\") }\n                if wrong > right { reasons.append(\"\\(wrong) calls moved to the wrong label against \\(right) to the right one\") }\n                verdict = reasons.isEmpty ? \"not necessary (R2)\" : \"necessary (R2)\"\n            case \"warp\":\n                if pass != true { reasons.append(\"the battery does not pass (\\(pass.map { $0 ? \"PASS\" : \"FAIL\" } ?? \"no report\"))\") }\n                if let agreement { if agreement < rules.minSensorAgreement { reasons.append(String(format: \"the sensor call agrees on %.1f%% (bar %.0f%%)\", agreement * 100, rules.minSensorAgreement * 100)) } }\n                else { reasons.append(\"no sensor call to compare\") }\n                for (what, x, y) in [(\"sensor\", a.iphoneSensorReal, b.iphoneSensorReal), (\"routed\", a.iphoneRoutedReal, b.iphoneRoutedReal)] {\n                    guard let x, let y else { reasons.append(\"no iPhone \\(what) share to compare\"); continue }\n                    if y < x - rules.maxRealShareDrop { reasons.append(String(format: \"the iPhone %@ real share fell from %.3f to %.3f\", what, x, y)) }\n                }\n                if loss > rules.maxCorrectLoss { reasons.append(\"the labelled final_mixed images lose \\(loss) correct calls (bar \\(rules.maxCorrectLoss))\") }\n                verdict = reasons.isEmpty ? \"holds up (R3)\" : \"does not hold up (R3)\"\n            default: break\n            }\n            return CompareReport(date: Date(), name: name, judge: judge, rules: rules.text, reference: a, variant: b, joined: joined, unmatched: unmatched,\n                                 moved: moved, movedToRight: right, movedToWrong: wrong, sensorCompared: compared, sensorAgreement: agreement,\n                                 battery: battery.map { datasetURL($0).path }, batteryPass: pass, batteryStatuses: statuses, verdict: verdict, reasons: reasons)\n        }\n\n        static func table(_ r: CompareReport) -> String {\n            func fm(_ s: CompareSide) -> String {\n                \"final_mixed correct \\(s.finalMixedCorrect.values.reduce(0, +)) of \\(s.finalMixedImages) (\" + s.finalMixedCorrect.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \") + \")\"\n                    + \"; labelled \\(s.labelledCorrect) of \\(s.labelledImages)\" + (s.warpCorrect.map { \"; the warp lens's own call \\($0)\" } ?? \"\")\n                    + (s.iphoneImages.map { n in String(format: \"; iPhone %d: sensor real %.3f, routed real %.3f\", n, s.iphoneSensorReal ?? .nan, s.iphoneRoutedReal ?? .nan) } ?? \"\")\n            }\n            var lines = [\"\\(r.name) (\\(r.judge)): \\(r.verdict)\"]\n            lines.append(\"  reference: \" + fm(r.reference))\n            lines.append(\"  variant:   \" + fm(r.variant))\n            lines.append(\"  \\(r.joined) images joined (\\(r.unmatched) unmatched); \\(r.moved) labelled calls moved, \\(r.movedToRight) to the right label, \\(r.movedToWrong) to the wrong one\")\n            lines.append(r.sensorAgreement.map { String(format: \"  sensor call agreement %.4f on %d images\", $0, r.sensorCompared) } ?? \"  sensor call: not compared\")\n            if let pass = r.batteryPass { lines.append(\"  battery: \\(pass ? \"PASS\" : \"FAIL\")\" + (r.batteryStatuses.map { \" \" + $0.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \") } ?? \"\")) }\n            for reason in r.reasons { lines.append(\"  - \" + reason) }\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/ResearchCondensed.swift","status":"added","lang":"swift","hunks":[[1,0,1,83]],"header":{"lines":[1,13],"target":"VeilGardeCLI","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":1650,"scopes":[["X","ResearchCommand",null,"",19,19,[19,26],83,null,-1,0,"a"],["S","Condensed",null,"",20,20,[20,38],82,null,0,0,"a"],["f","run",[],"",36,36,[36,26],65,null,1,0,"a"],["f","table",["_"],"static",67,67,[67,58],81,null,1,0,"a"],["f","pad",["_","_"],"",68,68,[68,54],68,null,3,12,"a"]],"old":"","new":"//\n//  ResearchCondensed.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research condensed`: trains the condensed model's pre-registered arms on MLX\n//        (CondensedTrainer), judges each by the admission rules, and writes the weights and the\n//        report for measurement.\n//  PIN:  One MLX workload. Reads final_mixed's tile cache, the store's rows, the scratch store\n//        (the noiseprint shard and the battery's) and the battery's tile cache. Writes\n//        <work area>/research/condensed-<stamp>.json and the weights under\n//        <work area>/research/condensed-<stamp>/; nothing reaches a bundle.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nextension ResearchCommand {\n    struct Condensed: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"condensed\", abstract: \"Train the condensed model's arms on MLX and judge them by the admission rules fixed before the run.\",\n            discussion: \"Needs the scratch store's final_mixed_np and battery_all shards and the battery's tile cache (features tiles <battery.jsonl>). One MLX workload.\")\n        @Option(name: .customLong(\"golden-report\"), help: \"A core or core-golden report whose golden columns make the golden core.\") var goldenReport: String?\n        @Option(help: \"The golden core's features, comma separated (instead of --golden-report).\") var golden: String?\n        @Option(help: \"Arms to run, comma separated (default: all).\") var arms: String?\n        @Option(help: \"The most epochs per run.\") var epochs = 40\n        @Option(help: \"Seeds, comma separated; the first is the candidate.\") var seeds = \"0,1,2\"\n        @Option(help: \"The warp tile cache (default: <work area>/store/tiles/final_mixed).\") var tiles: String?\n        @Option(help: \"The feature store (default: <work area>/store/shards).\") var store: String?\n        @Option(help: \"The scratch store (default: <work area>/store/aux).\") var aux: String?\n        @Option(name: .customLong(\"battery-tiles\"), help: \"The battery's tile cache (default: <work area>/store/tiles/battery).\") var batteryTiles: String?\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                var s = CondensedSettings()\n                s.epochs = epochs\n                s.seeds = try seeds.split(separator: \",\").map { text in\n                    guard let v = UInt64(text.trimmingCharacters(in: .whitespaces)) else { throw VeilGardeFailure.usage(\"--seeds is a list of integers, not \\(seeds)\") }\n                    return v\n                }\n                if let arms { s.arms = arms.split(separator: \",\").map { $0.trimmingCharacters(in: .whitespaces) } }\n                if let golden { s.golden = try WarpFeatures.columns(named: golden.split(separator: \",\").map { $0.trimmingCharacters(in: .whitespaces) }) }\n                if let goldenReport {\n                    let object = try JSONSerialization.jsonObject(with: Data(contentsOf: datasetURL(goldenReport))) as? [String: Any]\n                    guard let columns = (object?[\"golden\"] as? [String: Any])?[\"columns\"] as? [Int] else { throw VeilGardeFailure.data(\"\\(goldenReport) names no golden columns\") }\n                    s.golden = columns\n                }\n                let file = try ResearchCommand.output(area, \"condensed\")\n                let weights = file.deletingPathExtension()\n                let inputs = CondensedTrainer.Inputs(tiles: tiles.map(datasetURL) ?? area.tiles.appendingPathComponent(\"final_mixed\", isDirectory: true),\n                                                     store: store.map(datasetURL) ?? area.shards,\n                                                     aux: aux.map(datasetURL) ?? area.root.appendingPathComponent(\"store/aux\", isDirectory: true),\n                                                     batteryTiles: batteryTiles.map(datasetURL) ?? area.tiles.appendingPathComponent(\"battery\", isDirectory: true),\n                                                     bundle: try ShippedBundle.verified(), output: weights)\n                let report = try CondensedTrainer.run(inputs, settings: s, note: note)\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path); weights: \\(weights.path)\")\n            }\n        }\n\n        static func table(_ r: CondensedReport) -> String {\n            func pad(_ s: String, _ n: Int) -> String { s.count >= n ? s : s + String(repeating: \" \", count: n - s.count) }\n            var lines = [\"condensed: \" + r.counts.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \"),\n                         String(format: \"comparators on the test images: the trio warp model's vote AUC %.4f, %@ sensor real %@; the shipped fusion head's AUC %.4f (reliance)\",\n                                r.trioVoteAUC, r.settings.cameraPool, r.trioCameraRealShare.map { String(format: \"%.3f\", $0) } ?? \"—\", r.shippedFusionAUC)]\n            lines.append(\"  \" + pad(\"arm\", 24) + \"params  test AUC (seeds)          boosted  FPR@its recall  HARD battery  camera real  verdict\")\n            for a in r.arms {\n                lines.append(\"  \" + pad(a.arm.name, 24) + String(format: \"%6d  %.4f (%.4f ± %.4f)  %.4f   %.3f / %.3f   %2d of %2d      %@  %@\", a.parameters, a.model.auc, a.testAUCMean,\n                                                                    a.testAUCSpread, a.gbdt.auc, a.fprAtGBDTRecall, a.gbdt.realFPR, a.battery.hardRight, a.battery.hardImages,\n                                                                    a.model.cameraRealShare.map { String(format: \"%.3f\", $0) } ?? \"  —  \",\n                                                                    a.admissible ? \"admissible\" : \"fails \" + a.rules.filter { !$0.passed }.map { String($0.rule.prefix(2)) }.joined(separator: \", \")))\n                if !a.battery.wrong.isEmpty { lines.append(\"    HARD battery wrong: \" + a.battery.wrong.joined(separator: \", \")) }\n            }\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/ResearchCore.swift","status":"added","lang":"swift","hunks":[[1,0,1,109]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,8],"pin":[9,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1655,"scopes":[["S","CoreGoldenAcross",null,"",19,19,[19,33],24,[18,18],-1,0,"a"],["X","ResearchCommand",null,"",26,26,[26,26],109,null,-1,0,"a"],["S","Core",null,"",27,27,[27,33],108,null,1,0,"a"],["f","run",[],"",40,40,[40,26],71,null,2,0,"a"],["f","table",["_"],"static",73,73,[73,53],107,null,2,0,"a"],["f","pad",["_","_"],"",74,74,[74,54],74,null,4,12,"a"],["f","share",["_"],"",75,75,[75,47],75,null,4,12,"a"]],"old":"","new":"//\n//  ResearchCore.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research core`: the core study (CoreStudy) on the work area's tile cache, its\n//        report and its table; `--combine` applies the golden rule across the stem-split and the\n//        left-out-pool reports.\n//  PIN:  CPU work on cached tiles, no MLX. Writes <work area>/research/core-<stamp>.json (or\n//        core-golden-<stamp>.json). No flag moves a rule's tolerance: they are fixed in\n//        CoreSettings, which every report carries.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\n/// R2 across runs, as `research core --combine` writes it.\nstruct CoreGoldenAcross: Codable {\n    var date: Date\n    var reports: [String]\n    var perRun: [CoreGolden]\n    var golden: CoreGolden\n}\n\nextension ResearchCommand {\n    struct Core: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"core\", abstract: \"Refit the warp tile model on pre-registered feature subsets, 19 wide, and measure what moves the majority route.\",\n            discussion: \"The rules are fixed in code and written into the report. About 60 refits of the deployed shape on the tile cache; CPU only.\")\n        @Option(help: \"Registered arms to run, comma separated (default: all; all19, the seed controls and the trio always run).\") var arms: String?\n        @Option(help: \"Bootstrap resamples per comparison.\") var resamples = 1000\n        @Option(help: \"The warp tile cache (default: <work area>/store/tiles/final_mixed).\") var tiles: String?\n        @Option(name: .customLong(\"leave-pool-out\"), help: \"A source pool to take out of train and validation and score whole (iphone).\") var leavePoolOut: String?\n        @Flag(name: .customLong(\"no-forward\"), help: \"Skip the forward selection.\") var noForward = false\n        @Option(parsing: .upToNextOption, help: \"Instead of a run: core reports to judge together by the golden rule, the stem split first.\") var combine: [String] = []\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                if !combine.isEmpty {\n                    let reports = try combine.map { try JSONCoding.read(CoreReport.self, from: datasetURL($0)) }\n                    let across = CoreGoldenAcross(date: Date(), reports: combine.map { datasetURL($0).path }, perRun: reports.map(\\.golden),\n                                                  golden: CoreStudy.golden(across: reports))\n                    let file = try ResearchCommand.output(area, \"core-golden\")\n                    try JSONCoding.write(across, to: file)\n                    if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(across), to: json) }\n                    for (path, g) in zip(combine, across.perRun) { print(\"\\(path): \\(g.name) (\\(g.features.joined(separator: \", \")))\") }\n                    print(\"golden across \\(reports.count) runs: \\(across.golden.name) (\\(across.golden.features.joined(separator: \", \"))); \\(across.golden.reason)\")\n                    print(\"qualifying in every run: \" + (across.golden.qualifying.isEmpty ? \"none\" : across.golden.qualifying.joined(separator: \", \")))\n                    note(\"report: \\(file.path)\")\n                    return\n                }\n                var s = CoreSettings()\n                s.resamples = resamples\n                s.forwardSelection = !noForward\n                s.leavePoolOut = leavePoolOut\n                s.arms = arms.map { $0.split(separator: \",\").map { $0.trimmingCharacters(in: .whitespaces) } }\n                _ = try CoreStudy.chosenArms(s)\n                let inputs = CoreStudy.Inputs(tiles: tiles.map(datasetURL) ?? area.tiles.appendingPathComponent(\"final_mixed\", isDirectory: true),\n                                              bundle: try ShippedBundle.verified())\n                let report = try CoreStudy.run(inputs, settings: s, note: note)\n                let file = try ResearchCommand.output(area, \"core\")\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path)\")\n            }\n        }\n\n        static func table(_ r: CoreReport) -> String {\n            func pad(_ s: String, _ n: Int) -> String { s.count >= n ? s : s + String(repeating: \" \", count: n - s.count) }\n            func share(_ v: Double?) -> String { v.map { String(format: \"%.3f\", $0) } ?? \"  —  \" }\n            let p = r.partitions, camera = r.settings.cameraPool\n            var lines = [String(format: \"core: train %d images (%d tiles), validation %d, scored %d (%d tiles)%@; seed floor %.4f vote AUC\",\n                                p.trainImages, p.trainTiles, p.validationImages, p.scoredImages, p.scoredTiles,\n                                p.leftOutPool.map { \", the \\($0) pool's \\(p.leftOutImages) images left out of training and scored\" } ?? \"\", r.seedFloor)]\n            if let sh = r.shipped {\n                lines.append(String(format: \"shipped model (reliance: its own corpus): vote AUC %.4f, weighted %.4f; %@ real %@; generated called real %.3f\",\n                                    sh.metrics.imageMajorityAUC, sh.metrics.imageWeightedAUC, camera, share(sh.cameraRealShare), sh.sensor.generatedCalledReal))\n            }\n            lines.append(\"  \" + pad(\"arm\", 26) + \"cols  tile   weighted vote    vote vs trio [95%]          vs all19  moved  \\(pad(camera + \" real\", 11)) gen→real  R1 / distance / R2\")\n            for row in r.rows {\n                let t = row.againstTrio.vote, a = row.againstAll19.vote\n                lines.append(\"  \" + pad(row.arm.name, 26) + String(format: \"%4d  %.4f %.4f   %.4f  %+.4f [%+.4f, %+.4f]  %+.4f  %5d  \", row.arm.width, row.metrics.tileAUC,\n                                                                     row.metrics.imageWeightedAUC, row.metrics.imageMajorityAUC, t.delta, t.low, t.high, a.delta, a.changedCalls)\n                             + pad(share(row.cameraRealShare), 11) + \" \" + String(format: \"%.3f\", row.sensor.generatedCalledReal)\n                             + \"     \\(row.needle) / \\(row.distance) / \\(row.qualifies ? \"qualifies\" : \"—\")\")\n            }\n            if !r.forward.isEmpty { lines.append(\" forward selection from the trio:\") }\n            for step in r.forward {\n                lines.append(String(format: \"  step %d from %@: best %@ %+.4f [%+.4f, %+.4f] — %@\", step.step, step.base.joined(separator: \", \"), step.best,\n                                    step.gain, step.low, step.high, step.stopped.map { \"stop: \\($0)\" } ?? \"added\"))\n            }\n            let reference = r.rows[0]\n            let golden = r.rows.first { $0.arm.name == r.golden.name } ?? reference\n            lines.append(\" sensor calls by pool, all19 | \\(golden.arm.name) (real / inconclusive / generated):\")\n            for pool in reference.pools {\n                let g = golden.pools.first { $0.pool == pool.pool && $0.label == pool.label }\n                lines.append(\"  \" + pad(\"\\(pool.pool) (\\(pool.label == 1 ? \"generated\" : \"real\"))\", 26) + String(format: \"%4d  %.3f / %.3f / %.3f  |  %.3f / %.3f / %.3f\",\n                             pool.images, pool.real, pool.inconclusive, pool.generated, g?.real ?? .nan, g?.inconclusive ?? .nan, g?.generated ?? .nan))\n            }\n            lines.append(\"golden (this run): \\(r.golden.name) (\\(r.golden.features.joined(separator: \", \"))) — \\(r.golden.reason)\")\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/ResearchRedundancy.swift","status":"added","lang":"swift","hunks":[[1,0,1,78]],"header":{"lines":[1,11],"target":"VeilGardeCLI","what":[6,7],"pin":[8,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":1662,"scopes":[["X","ResearchCommand",null,"",17,17,[17,26],78,null,-1,0,"a"],["S","Redundancy",null,"",18,18,[18,39],77,null,0,0,"a"],["f","run",[],"",31,31,[31,26],53,null,1,0,"a"],["f","table",["_"],"static",55,55,[55,59],76,null,1,0,"a"],["f","pad",["_","_"],"",56,56,[56,54],56,null,3,12,"a"]],"old":"","new":"//\n//  ResearchRedundancy.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde research redundancy`: the redundancy check (RedundancyStudy) on final_mixed's\n//        tile cache, the store's rows and the scratch store's noiseprint, its report and its table.\n//  PIN:  CPU work on cached tiles and stored features. The golden arm's columns come from a core\n//        report (`research core` or its `--combine`) or are named. Writes\n//        <work area>/research/redundancy-<stamp>.json.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nextension ResearchCommand {\n    struct Redundancy: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"redundancy\", abstract: \"Ask whether the noiseprint's and the fusion head's signals are already in the warp residual, arm by arm.\",\n            discussion: \"Needs the noiseprint of final_mixed's store rows in a scratch store: features extract <list> --columns noiseprint --shard final_mixed_np --store <aux>.\")\n        @Option(name: .customLong(\"golden-report\"), help: \"A core report or core-golden report whose golden columns make the golden arm.\") var goldenReport: String?\n        @Option(help: \"The golden arm's features, comma separated (instead of --golden-report).\") var golden: String?\n        @Option(help: \"Bootstrap resamples per comparison.\") var resamples = 1000\n        @Option(help: \"The warp tile cache (default: <work area>/store/tiles/final_mixed).\") var tiles: String?\n        @Option(help: \"The feature store (default: <work area>/store/shards).\") var store: String?\n        @Option(help: \"The scratch store holding final_mixed_np (default: <work area>/store/aux).\") var aux: String?\n        @Option(help: \"Write the report here too (`-` for stdout).\") var json: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                var s = RedundancySettings()\n                s.resamples = resamples\n                if let golden { s.golden = try WarpFeatures.columns(named: golden.split(separator: \",\").map { $0.trimmingCharacters(in: .whitespaces) }) }\n                if let goldenReport {\n                    let object = try JSONSerialization.jsonObject(with: Data(contentsOf: datasetURL(goldenReport))) as? [String: Any]\n                    guard let columns = (object?[\"golden\"] as? [String: Any])?[\"columns\"] as? [Int] else { throw VeilGardeFailure.data(\"\\(goldenReport) names no golden columns\") }\n                    s.golden = columns\n                }\n                let inputs = RedundancyStudy.Inputs(tiles: tiles.map(datasetURL) ?? area.tiles.appendingPathComponent(\"final_mixed\", isDirectory: true),\n                                                    store: store.map(datasetURL) ?? area.shards,\n                                                    aux: aux.map(datasetURL) ?? area.root.appendingPathComponent(\"store/aux\", isDirectory: true),\n                                                    bundle: try ShippedBundle.verified())\n                let report = try RedundancyStudy.run(inputs, settings: s, note: note)\n                let file = try ResearchCommand.output(area, \"redundancy\")\n                try JSONCoding.write(report, to: file)\n                if let json { try emitJSON(try JSONCoding.prettyEncoder().encode(report), to: json) }\n                print(Self.table(report))\n                note(\"report: \\(file.path)\")\n            }\n        }\n\n        static func table(_ r: RedundancyReport) -> String {\n            func pad(_ s: String, _ n: Int) -> String { s.count >= n ? s : s + String(repeating: \" \", count: n - s.count) }\n            var lines = [\"redundancy: \" + r.counts.sorted { $0.key < $1.key }.map { \"\\($0.key) \\($0.value)\" }.joined(separator: \", \")]\n            for arm in r.arms {\n                lines.append(\"\\(arm.name) (\\(arm.features.joined(separator: \", \"))); cuts \\(String(format: \"%.4f / %.4f\", arm.cuts.realAtOrBelow, arm.cuts.generatedAtOrAbove))\")\n                for x in arm.reconstruction {\n                    lines.append(\"  reconstructs the \\(x.target) call: \" + String(format: \"AUC %.4f on %d images (%d positive), Spearman %.3f — %@\", x.auc, x.images, x.positives, x.spearman,\n                                                                                    x.reconstructed ? \"reconstructed (RR2)\" : \"not reconstructed\"))\n                }\n                lines.append(\"  cross-fitted AUC: \" + arm.aucs.sorted { $0.key < $1.key }.map { String(format: \"%@ %.4f\", $0.key, $0.value) }.joined(separator: \"; \"))\n                for g in arm.gains {\n                    let c = g.comparison\n                    lines.append(\"  \" + pad(g.name, 42) + String(format: \"%+.4f [%+.4f, %+.4f], moved %d — %@\", c.delta, c.low, c.high, c.changedCalls, g.verdict))\n                }\n                let v = arm.coverage\n                lines.append(\"  combiner replay on \\(v.captureAbsent) capture-absent images: the noiseprint moves \\(v.noiseprintMoved) calls, \\(v.noiseprintMovedRight) to the right label; the sensor call had \\(v.movedSensorRight) of them right\")\n                lines.append(\"  fusion against the warp lens's own call: \\(v.fusionWarpDisagree) differ, fusion right \\(v.fusionRight), warp right \\(v.warpRight)\")\n                let c = arm.camera\n                lines.append(\"  \\(r.settings.cameraPool) (\\(c.images)): sensor real and noiseprint camera \\(c.sensorRealCamera), sensor real only \\(c.sensorRealNoCamera), noiseprint camera only \\(c.sensorOtherCamera), neither \\(c.sensorOtherNoCamera)\")\n            }\n            return lines.joined(separator: \"\\n\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Route.swift","status":"added","lang":"swift","hunks":[[1,0,1,125]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,10],"pin":[11,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1667,"scopes":[["S","RouteCommand",null,"",18,18,[18,37],53,null,-1,0,"a"],["f","run",[],"",30,30,[30,22],52,null,0,0,"a"],["S","FuseCommand",null,"",55,55,[55,36],79,null,-1,0,"a"],["f","run",[],"",64,64,[64,22],78,null,2,0,"a"],["S","BatchCommand",null,"",81,81,[81,37],125,null,-1,0,"a"],["f","run",[],"",89,89,[89,22],124,null,4,0,"a"]],"old":"","new":"//\n//  Route.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde route <image>`: the full detector. The router picks the domain, the base expert\n//        runs (camera: warp lens + fusion; screenshot: the content head), and the specialists,\n//        the frame seam and the semantic chain compound on it. Prints the domain, the verdict and\n//        the specialist stack, the full patch map with --map, or the schema-v2 JSON with --json.\n//        Replaces Garde's headless --route / --route-json.\n//  PIN:  --json writes Garde's route bytes: times_sec [], device \"route\", route = the domain.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct RouteCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"route\", abstract: \"Run the full detector: route, base expert, specialist stack, mechanisms.\")\n\n    @Argument(help: \"The image.\") var image: String\n    @OptionGroup var route: RouteOptions\n    @OptionGroup var expert: BaseExpertOptions\n    @Option(help: \"Skip domain detection: camera or screenshot.\") var hint: String?\n    @Flag(help: \"The schema-v2 JSON on stdout.\") var json = false\n    @Flag(help: \"Print the patch map and every verdict, as `score` does.\") var map = false\n    @Flag(name: .customLong(\"no-color\"), help: \"No terminal colours.\") var noColor = false\n    @Flag(help: \"Run MLX on the CPU.\") var cpu = false\n\n    func run() throws {\n        guarded {\n            var config = try route.config()\n            config.baseExpert = try expert.resolve()\n            let domainHint = try parseHint(hint)\n            let cg = try loadImage(image)\n            let ((routed), seconds) = try LensRuntime.withDevice(cpu: cpu) { try timed { try Detector.shared.detect(cgImage: cg, config: config, hint: domainHint) } }\n            let r = routed.result\n            if json {\n                try emitJSON(try ResultJSON.encode(r, times: [], device: \"route\", route: routed.domain.rawValue), to: \"-\")\n                return\n            }\n            if map {\n                print(PatchMap.render(r, imagePath: image, model: \"domain \\(routed.domain.rawValue)\", times: [seconds], device: LensRuntime.deviceName(cpu: cpu),\n                                      color: !noColor && isatty(STDOUT_FILENO) == 1), terminator: \"\")\n                return\n            }\n            let stack = (r.specialists ?? []).map { String(format: \"%@(p=%.2f w=%.1f→%@)\", $0.name, $0.pAI, $0.weight, $0.verdict) }.joined(separator: \" + \")\n            print(String(format: \"route  domain=%@  verdict=%@  p=%.4f  majority=%@:%@  tile-map=%@\\n  stack: %@\",\n                         routed.domain.rawValue, r.weightedPrediction, r.weightedScore, PatchMap.sourceLabel(r.majoritySource), r.majorityPrediction,\n                         PatchMap.sourceLabel(r.tileMapSource), stack))\n        }\n    }\n}\n\nstruct FuseCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"fuse\", abstract: \"The camera base expert alone: the warp lens and the fusion head, no specialists.\")\n\n    @Argument(help: \"The image.\") var image: String\n    @OptionGroup var detection: DetectionOptions\n    @Option(help: \"DINOv2 weights: small, xsmall or xxsmall.\") var dino: String = DinoVariant.small.rawValue\n    @Option(help: \"Write the schema-v2 JSON to this path, or - for stdout only.\") var json: String?\n    @Flag(name: .customLong(\"no-color\"), help: \"No terminal colours.\") var noColor = false\n\n    func run() throws {\n        guarded {\n            var config = try detection.config()\n            guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino must be small, xsmall or xxsmall\") }\n            config.dinoVariant = variant\n            let cg = try loadImage(image)\n            let (r, seconds) = try LensRuntime.withDevice(cpu: detection.cpu) { try timed { try Fusion.run(cgImage: cg, config: config) } }\n            let device = LensRuntime.deviceName(cpu: detection.cpu)\n            if let json {\n                try emitJSON(try ResultJSON.encode(r, times: [seconds], device: device), to: json)\n                if json == \"-\" { return }\n            }\n            print(PatchMap.render(r, imagePath: image, model: \"fusion\", times: [seconds], device: device, color: !noColor && isatty(STDOUT_FILENO) == 1), terminator: \"\")\n        }\n    }\n}\n\nstruct BatchCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"batch\", abstract: \"Route a JSONL manifest of {id, path, hint} rows, in order, into a JSONL of results.\")\n\n    @Argument(help: \"The manifest: one {\\\"id\\\", \\\"path\\\", \\\"hint\\\"} object per line.\") var input: String\n    @Argument(help: \"The output JSONL; it must not exist.\") var output: String\n    @OptionGroup var route: RouteOptions\n    @OptionGroup var expert: BaseExpertOptions\n\n    func run() throws {\n        guarded {\n            let inputURL = URL(fileURLWithPath: (input as NSString).expandingTildeInPath).standardizedFileURL\n            let outputURL = URL(fileURLWithPath: (output as NSString).expandingTildeInPath).standardizedFileURL\n            guard inputURL.resolvingSymlinksInPath() != outputURL.resolvingSymlinksInPath() else { throw VeilGardeFailure.usage(\"the input and output paths must differ\") }\n            guard !FileManager.default.fileExists(atPath: outputURL.path) else { throw VeilGardeFailure.exists(\"refusing to overwrite \\(outputURL.path)\") }\n            var config = try route.config()\n            config.baseExpert = try expert.resolve()\n            // The whole manifest validates before any inference.\n            let items = try RouteBatch.parse(Data(contentsOf: inputURL))\n            let temporary = outputURL.deletingLastPathComponent().appendingPathComponent(\".\\(outputURL.lastPathComponent).tmp-\\(UUID().uuidString)\")\n            guard FileManager.default.createFile(atPath: temporary.path, contents: nil) else { throw VeilGardeFailure.internalError(\"cannot create \\(temporary.path)\") }\n            do {\n                let handle = try FileHandle(forWritingTo: temporary)\n                for (index, item) in items.enumerated() {\n                    defer { LensRuntime.releaseMemory() }\n                    let cg = try loadImage(item.path)\n                    let routed = try Detector.shared.detect(cgImage: cg, config: config, hint: item.hint)\n                    var line = Data(\"{\\\"id\\\":\".utf8)\n                    line.append(try JSONEncoder().encode(item.id))\n                    line.append(Data(\",\\\"result\\\":\".utf8))\n                    line.append(try ResultJSON.encode(routed.result, times: [], device: \"route-batch\", route: routed.domain.rawValue))\n                    line.append(Data(\"}\\n\".utf8))\n                    try handle.write(contentsOf: line)\n                    if (index + 1).isMultiple(of: 64) { try handle.synchronize(); note(\"batch: \\(index + 1)/\\(items.count)\") }\n                }\n                try handle.synchronize()\n                try handle.close()\n                try FileManager.default.moveItem(at: temporary, to: outputURL)\n                note(\"batch: \\(items.count) results → \\(outputURL.path)\")\n            } catch {\n                try? FileManager.default.removeItem(at: temporary)\n                throw error\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Score.swift","status":"added","lang":"swift","hunks":[[1,0,1,56]],"header":{"lines":[1,11],"target":"VeilGardeCLI","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":1673,"scopes":[["S","ScoreCommand",null,"",17,17,[17,37],56,null,-1,0,"a"],["f","run",[],"",32,32,[32,22],55,null,0,0,"a"]],"old":"","new":"//\n//  Score.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde score <image>`: the warp lens alone, the camera-sensor score included. Prints\n//        the patch map and both verdicts, or the schema-v2 JSON with --json (a path, or - for\n//        stdout only). Replaces `garde <image>`, Garde's headless run.\n//  PIN:  The same pipeline Garde's main mode ran (runInferenceFast), so `--json -` here and there\n//        differ only in times_sec and the sensor fields the two cuts changed (ResultJSON.changedSinceGarde).\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct ScoreCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"score\", abstract: \"Score an image with the warp lens: the camera-sensor score and the weighted verdict.\")\n\n    @Argument(help: \"The image (JPEG, PNG, HEIC, WebP…).\")\n    var image: String\n    @OptionGroup var detection: DetectionOptions\n    @Option(help: \"Write the schema-v2 JSON to this path, or - for stdout only.\")\n    var json: String?\n    @Option(help: \"Run the inference this many times (run 1 includes Metal warmup).\")\n    var `repeat`: Int = 1\n    @Option(name: .customLong(\"dump-features\"), help: \"Write the tile feature matrix (Garde's --dump-features format) to this path.\")\n    var dumpFeatures: String?\n    @Flag(name: .customLong(\"no-color\"), help: \"No terminal colours.\")\n    var noColor = false\n\n    func run() throws {\n        guarded {\n            var config = try detection.config()\n            config.featureDumpURL = dumpFeatures.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath) }\n            let cg = try loadImage(image)\n            var times = [Double]()\n            var result: InferenceResult?\n            try LensRuntime.withDevice(cpu: detection.cpu) {\n                for _ in 0..<max(1, self.repeat) {\n                    let (r, seconds) = try timed { try WarpInference.run(cgImage: cg, config: config) }\n                    result = r\n                    times.append(seconds)\n                }\n            }\n            guard let r = result else { throw VeilGardeFailure.internalError(\"no result\") }\n            let device = LensRuntime.deviceName(cpu: detection.cpu)\n            if let json {\n                try emitJSON(try ResultJSON.encode(r, times: times, device: device), to: json)\n                if json == \"-\" { return }\n            }\n            let color = !noColor && isatty(STDOUT_FILENO) == 1\n            print(PatchMap.render(r, imagePath: image, model: config.modelURL.lastPathComponent, times: times, device: device, color: color), terminator: \"\")\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Train.swift","status":"added","lang":"swift","hunks":[[1,0,1,245]],"header":{"lines":[1,15],"target":"VeilGardeCLI","what":[6,10],"pin":[11,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1675,"scopes":[["S","TrainingOptions",null,"",21,21,[21,42],81,null,-1,0,"a"],["f","candidateID",["_"],"",29,29,[29,47],35,null,0,0,"a"],["f","engine",[],"",37,37,[37,43],50,null,0,0,"a"],["f","run",["_"],"",53,53,[53,46],69,[52,52],0,0,"a"],["f","metricsFile",["_"],"",71,71,[71,48],80,null,0,0,"a"],["f","datasetURL",["_"],"",83,83,[83,39],83,null,-1,8,"a"],["S","TrainCommand",null,"",85,85,[85,37],245,null,-1,0,"a"],["S","Plan",null,"",91,91,[91,33],108,null,6,0,"a"],["f","run",[],"",97,97,[97,26],107,null,7,0,"a"],["S","Warp",null,"",110,110,[110,33],138,null,6,0,"a"],["f","run",[],"",122,122,[122,26],137,null,9,0,"a"],["S","Calibration",null,"",140,140,[140,40],154,null,6,0,"a"],["f","run",[],"",147,147,[147,26],153,null,11,0,"a"],["S","Fusion",null,"",156,156,[156,35],177,null,6,0,"a"],["f","run",[],"",165,165,[165,26],176,null,13,0,"a"],["S","Heads",null,"",179,179,[179,34],195,null,6,0,"a"],["f","run",[],"",184,184,[184,26],194,null,15,0,"a"],["S","Combine",null,"",197,197,[197,36],205,null,6,0,"a"],["f","run",[],"",202,202,[202,26],204,null,17,0,"a"],["S","Noiseprint",null,"",207,207,[207,39],224,null,6,0,"a"],["f","run",[],"",218,218,[218,26],223,null,19,0,"a"],["S","All",null,"",226,226,[226,32],234,null,6,0,"a"],["f","run",[],"",231,231,[231,26],233,null,21,0,"a"],["S","Run",null,"",236,236,[236,32],244,null,6,0,"a"],["f","run",[],"",241,241,[241,26],243,null,23,0,"a"]],"old":"","new":"//\n//  Train.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde train`: every model VeilGarde ships, trained into a candidate bundle at\n//        <work area>/candidates/<id>/ that `veilgarde route --bundle` runs. `plan` prints what a\n//        recipe would do without doing it; `warp`, `calibration`, `fusion`, `heads`,\n//        `combiner` and `noiseprint` train one model (warp brings its calibration unless told\n//        not to); `all` trains the shipped preset and `run` a recipe.toml.\n//  PIN:  The parent bundle is the shipped one unless --parent names another (a candidate, or\n//        <work area>/live). The store defaults to <work area>/store/shards; --store names\n//        another (any store in the same shard format reads as is). Train in release:\n//        VEILGARDE_CONFIG=release scripts/cli.sh train …\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct TrainingOptions: ParsableArguments {\n    @OptionGroup var workArea: WorkAreaOptions\n    @Option(help: \"The bundle the candidate starts from (default: the shipped bundle; `live` for <work area>/live).\") var parent: String?\n    @Option(help: \"The feature store directory (default: <work area>/store/shards).\") var store: String?\n    @Option(help: \"The candidate's id, its folder under <work area>/candidates (default: <what>-<date>-<time>).\") var id: String?\n    @Flag(help: \"Replace a candidate with the same id.\") var replace = false\n    @Flag(help: \"Print the plan and stop.\") var plan = false\n\n    func candidateID(_ what: String) -> String {\n        if let id { return id }\n        let f = DateFormatter()\n        f.locale = Locale(identifier: \"en_US_POSIX\")\n        f.dateFormat = \"yyyyMMdd-HHmmss\"\n        return \"\\(what)-\\(f.string(from: Date()))\"\n    }\n\n    func engine() throws -> TrainingEngine {\n        let area = try workArea.resolve()\n        let parentURL: URL\n        switch parent {\n        case nil: parentURL = ShippedBundle.directory\n        case \"live\"?: parentURL = area.root.appendingPathComponent(\"live\", isDirectory: true)\n        case let path?: parentURL = URL(fileURLWithPath: (path as NSString).expandingTildeInPath, isDirectory: true)\n        }\n        let storeURL = store.map { URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true) }\n        ShippedBundle.registerWeightFolders(workArea: area)\n        let engine = TrainingEngine(area: area, parent: parentURL, store: storeURL) { event in if let line = event.line { note(line) } }\n        engine.replace = replace\n        return engine\n    }\n\n    /// Plans, prints the plan (to stdout with --plan, else to stderr) and trains unless --plan.\n    func run(_ recipe: TrainingRecipe) throws {\n        let engine = try self.engine()\n        let plan = try engine.plan(recipe)\n        if self.plan {\n            print(plan.summary)\n            if !plan.refusals.isEmpty { throw VeilGardeFailure.usage(\"the recipe is refused:\\n  \" + plan.refusals.joined(separator: \"\\n  \")) }\n            return\n        }\n        note(plan.summary)\n        let outcome = try engine.train(recipe)\n        print(\"candidate \\(outcome.candidate.id): \\(outcome.candidate.root.path)\")\n        print(String(format: \"  %d artifacts, trained in %.1fs\", outcome.candidate.manifest.artifacts.count, outcome.seconds))\n        for model in recipe.ordered.map(\\.name) { print(\"  \\(model): \\(outcome.candidate.root.path)/\\(metricsFile(model))\") }\n        let noiseprint = recipe.models.contains { if case .noiseprint = $0 { return true } else { return false } }\n        print(\"run it:  veilgarde route <image> --bundle \\(outcome.candidate.root.path)\"\n              + (noiseprint ? \" --weights-dir \\(outcome.candidate.root.path)/noiseprint\" : \"\"))\n    }\n\n    func metricsFile(_ model: String) -> String {\n        switch model {\n        case \"warp-tile\": return \"warp/metrics.json\"\n        case \"sensor-calibration\": return \"calibration/metrics.json\"\n        case \"fusion-head\": return \"fusion/metrics.json\"\n        case \"combiner\": return \"combiner/metrics.json\"\n        case \"noiseprint\": return \"noiseprint/metrics.json\"\n        default: return \"heads/\\(model.dropFirst(\"head:\".count))/metrics.json\"\n        }\n    }\n}\n\nfunc datasetURL(_ path: String) -> URL { URL(fileURLWithPath: (path as NSString).expandingTildeInPath) }\n\nstruct TrainCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"train\", abstract: \"Train VeilGarde's models into a candidate bundle: the warp tile model, its calibration, the fusion head, the heads, the combiner, the noiseprint.\",\n        discussion: \"Train in release (VEILGARDE_CONFIG=release scripts/cli.sh train …). A candidate is a full bundle: run it with `veilgarde route <image> --bundle <candidate>`.\",\n        subcommands: [Plan.self, Warp.self, Calibration.self, Fusion.self, Heads.self, Combine.self, Noiseprint.self, All.self, Run.self])\n\n    struct Plan: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"plan\", abstract: \"Print what a recipe would train and why, without training (no MLX, no writes).\")\n        @Option(help: \"A recipe.toml.\") var recipe: String?\n        @Option(help: \"The shipped preset over this dataset (final_mixed's folder or a dataset.jsonl).\") var preset: String?\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                let r: TrainingRecipe\n                if let recipe { r = try RecipeFile.load(datasetURL(recipe)) } else if let preset {\n                    r = TrainingRecipe.shipped(id: options.candidateID(\"shipped\"), dataset: datasetURL(preset))\n                } else { throw VeilGardeFailure.usage(\"name a --recipe file or a --preset dataset\") }\n                let plan = try options.engine().plan(r)\n                print(plan.summary)\n                if !plan.refusals.isEmpty { throw VeilGardeFailure.usage(\"the recipe is refused:\\n  \" + plan.refusals.joined(separator: \"\\n  \")) }\n            }\n        }\n    }\n\n    struct Warp: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"warp\", abstract: \"Train the warp tile model on a dataset's tiles (and its sensor calibration).\")\n        @Option(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl.\") var dataset: String\n        @Option(help: \"deployed (optimal_8's shape) or v18.\") var shape: String = WarpShape.deployed.rawValue\n        @Option(name: .customLong(\"sample-per-label\"), help: \"At most this many images of each label (a quick run).\") var samplePerLabel: Int?\n        @Option(help: \"Override the shape's tree count.\") var trees: Int?\n        @Option(help: \"Override the shape's depth.\") var depth: Int?\n        @Option(help: \"Override the shape's learning rate.\") var eta: Double?\n        @Option(help: \"Split only on these warp features, comma separated (FR,LV,CV,…); the model stays 19 wide.\") var features: String?\n        @Flag(name: .customLong(\"no-calibration\"), help: \"Do not refit the calibration (the sensor lane then falls back to identity).\") var noCalibration = false\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                guard let s = WarpShape(rawValue: shape) else { throw VeilGardeFailure.usage(\"--shape is deployed or v18, not \\(shape)\") }\n                var w = WarpTileModel(dataset: datasetURL(dataset)).shape(s)\n                if let samplePerLabel { w = w.sample(perLabel: samplePerLabel) }\n                if let trees { w = w.trees(trees) }\n                if let depth { w = w.depth(depth) }\n                if let eta { w = w.eta(eta) }\n                if let features { w = try w.features(features.split(separator: \",\").map { $0.trimmingCharacters(in: .whitespaces) }) }\n                let calibrate = !noCalibration\n                try options.run(TrainingRecipe(id: options.candidateID(\"warp\")) {\n                    w\n                    if calibrate { SensorCalibration() }\n                })\n            }\n        }\n    }\n\n    struct Calibration: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"calibration\", abstract: \"Refit the parent's sensor calibration on a dataset's validation images.\")\n        @Option(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl.\") var dataset: String\n        @Option(name: .customLong(\"max-real-fpr\"), help: \"The real false-positive ceiling the threshold is chosen under.\") var maxRealFPR: Double = 0.10\n        @Option(help: \"The inconclusive band.\") var band: Double = 0.04\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                try options.run(TrainingRecipe(id: options.candidateID(\"calibration\")) {\n                    SensorCalibration(dataset: datasetURL(dataset)).maxRealFPR(maxRealFPR).band(band)\n                })\n            }\n        }\n    }\n\n    struct Fusion: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"fusion\", abstract: \"Train the fusion head on the store: a warm start on the parent's (the flywheel's way) or from scratch.\")\n        @Option(help: \"warm or scratch.\") var mode: String = \"warm\"\n        @Option(help: \"Trees to add (warm) or to grow (scratch).\") var trees: Int?\n        @Option(help: \"The learning rate.\") var eta: Double?\n        @Option(name: .customLong(\"new-generator-weight\"), help: \"The weight on new-generator rows.\") var newGeneratorWeight: Double = 1.0\n        @Flag(name: .customLong(\"allow-mixed-warp\"), help: \"Train on rows whose warp column came from different warp models.\") var allowMixedWarp = false\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                var f = FusionHead().newGeneratorWeight(newGeneratorWeight)\n                switch mode {\n                case \"warm\": f = f.warmStart(add: trees ?? 80, eta: eta ?? 0.03)\n                case \"scratch\": f = f.scratch(trees: trees ?? 500, eta: eta ?? 0.04)\n                default: throw VeilGardeFailure.usage(\"--mode is warm or scratch, not \\(mode)\")\n                }\n                if allowMixedWarp { f = f.allowMixedWarp() }\n                try options.run(TrainingRecipe(id: options.candidateID(\"fusion\")) { f })\n            }\n        }\n    }\n\n    struct Heads: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"heads\", abstract: \"Train specialist heads on the store's dino_norm column (each head's recipe, admission measured).\")\n        @Option(help: \"Comma-separated kinds (default: art,blur,human,cgi).\") var kinds: String = HeadKind.flywheelCategories.map(\\.rawValue).joined(separator: \",\")\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                let parsed = try kinds.split(separator: \",\").map { name -> HeadKind in\n                    guard let kind = HeadKind(rawValue: String(name)) else {\n                        throw VeilGardeFailure.usage(\"unknown head \\(name); heads are \\(HeadKind.allCases.map(\\.rawValue).joined(separator: \", \"))\")\n                    }\n                    return kind\n                }\n                try options.run(TrainingRecipe(id: options.candidateID(\"heads\")) { for kind in parsed { DinoHead(kind) } })\n            }\n        }\n    }\n\n    struct Combine: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"combiner\", abstract: \"Fit the stack combiner on the store's capture-absent rows under the parent's base and heads.\")\n        @Option(name: .customLong(\"reals-weight\"), help: \"The weight on real rows.\") var realsWeight: Double = 3\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(TrainingRecipe(id: options.candidateID(\"combiner\")) { Combiner().realsWeight(realsWeight) }) }\n        }\n    }\n\n    struct Noiseprint: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"noiseprint\", abstract: \"Train the noiseprint CNN from camera originals against everything that is not a capture (GPU).\",\n            discussion: \"The v202 recipe on the T9's folders. The net is frozen in the flywheel; the candidate carries it for measurement (route with --weights-dir <candidate>/noiseprint).\")\n        @Option(help: \"Epochs.\") var epochs: Int = 6\n        @Option(help: \"The batch size.\") var batch: Int = 256\n        @Option(name: .customLong(\"per-family\"), help: \"Images per negative family (three quarters train).\") var perFamily: Int = 120\n        @Option(help: \"The seed for the weights and the epoch order.\") var seed: UInt64 = 0\n        @Flag(name: .customLong(\"no-patch-cache\"), help: \"Cut the patches again instead of reading the work area's cache.\") var noPatchCache = false\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded {\n                let n = NoiseprintModel().epochs(epochs).batch(batch).perFamily(perFamily).seed(seed).cachePatches(!noPatchCache)\n                try options.run(TrainingRecipe(id: options.candidateID(\"noiseprint\")) { n })\n            }\n        }\n    }\n\n    struct All: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"all\", abstract: \"Train the shipped preset: every model VeilGarde ships that a dataset and the store reproduce.\")\n        @Option(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl, for the warp tile model.\") var dataset: String\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(TrainingRecipe.shipped(id: options.candidateID(\"shipped\"), dataset: datasetURL(dataset))) }\n        }\n    }\n\n    struct Run: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"run\", abstract: \"Train a recipe.toml.\")\n        @Argument(help: \"The recipe file.\") var recipe: String\n        @OptionGroup var options: TrainingOptions\n\n        func run() throws {\n            guarded { try options.run(try RecipeFile.load(datasetURL(recipe))) }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Watermark.swift","status":"added","lang":"swift","hunks":[[1,0,1,151]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,10],"pin":[11,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1700,"scopes":[["S","WatermarkCommand",null,"",18,18,[18,41],151,null,-1,0,"a"],["f","signature",["_"],"static",24,24,[24,71],31,null,0,0,"a"],["S","Sign",null,"",33,33,[33,33],45,null,0,0,"a"],["f","run",[],"",38,38,[38,26],44,null,2,0,"a"],["S","Match",null,"",47,47,[47,34],63,null,0,0,"a"],["f","run",[],"",54,54,[54,26],62,null,4,0,"a"],["S","Verify",null,"",65,65,[65,35],77,null,0,0,"a"],["f","run",[],"",70,70,[70,26],76,null,6,0,"a"],["S","Accept",null,"",79,79,[79,35],117,null,0,0,"a"],["f","run",[],"",88,88,[88,26],116,null,8,0,"a"],["S","Invariance",null,"",119,119,[119,39],150,null,0,0,"a"],["f","run",[],"",127,127,[127,26],149,null,10,0,"a"]],"old":"","new":"//\n//  Watermark.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde watermark`: a crop-robust signature read off an image's warp fragility\n//        pattern. `sign` prints it (vw1 text, or JSON); `match` finds where an image (a crop, a\n//        re-encode) sits on a signature; `verify` is match with the verdict as the exit code;\n//        `accept` runs v1's acceptance on final_mixed and evaluates its kill criterion;\n//        `invariance` signs a set of images and, against a baseline, fails on any change.\n//  PIN:  Native resolution, one MLX workload. `accept` and `invariance` write only their reports.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct WatermarkCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"watermark\", abstract: \"Sign an image by its warp fragility pattern, and find a crop or a re-encode of it again.\",\n        discussion: \"v1 is a design under measurement: run `watermark accept` before relying on it.\",\n        subcommands: [Sign.self, Match.self, Verify.self, Accept.self, Invariance.self])\n\n    static func signature(_ text: String) throws -> WatermarkSignature {\n        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)\n        if trimmed.hasPrefix(\"vw1:\") { return try WatermarkSignature(compact: trimmed) }\n        let url = datasetURL(trimmed)\n        let body = try String(contentsOf: url, encoding: .utf8).trimmingCharacters(in: .whitespacesAndNewlines)\n        if body.hasPrefix(\"vw1:\") { return try WatermarkSignature(compact: body) }\n        return try JSONDecoder().decode(WatermarkSignature.self, from: Data(body.utf8))\n    }\n\n    struct Sign: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"sign\", abstract: \"Print an image's watermark signature (vw1 text, or JSON with --json).\")\n        @Argument(help: \"The image.\") var image: String\n        @Flag(help: \"JSON instead of vw1 text.\") var json = false\n\n        func run() throws {\n            guarded {\n                let sig = try Watermark.sign(try loadImage(image))\n                if json { try emitJSON(try JSONCoding.prettyEncoder().encode(sig), to: \"-\") } else { print(sig.compact) }\n                note(\"\\(sig.rows)×\\(sig.cols) tiles, \\(sig.codes.count) sections, \\(sig.measuredBits) bits, cid \\(sig.cid.prefix(16))\")\n            }\n        }\n    }\n\n    struct Match: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"match\", abstract: \"Find where an image sits on a signature: offset, phase, score and its z-score.\")\n        @Argument(help: \"The image (a crop or a re-encode of a signed one).\") var image: String\n        @Argument(help: \"The signature: vw1 text, or a file holding vw1 text or JSON.\") var signature: String\n        @Option(help: \"Grid phases in pixels, comma-separated.\") var phases: String = \"0,8,16,24\"\n        @Flag(help: \"JSON instead of text.\") var json = false\n\n        func run() throws {\n            guarded {\n                let p = phases.split(separator: \",\").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }\n                let r = try Watermark.match(try loadImage(image), against: try WatermarkCommand.signature(signature), options: MatchOptions(phases: p))\n                if json { try emitJSON(try JSONCoding.prettyEncoder().encode(r), to: \"-\"); return }\n                print(String(format: \"%@: score %.4f over %d bits (z %.1f); offset (%d, %d) tiles at phase (%d, %d) px, the image's origin at (%d, %d) on the signed image\",\n                             r.matched ? \"match\" : \"no match\", r.score, r.bitsCompared, r.zScore, r.offsetX, r.offsetY, r.phaseX, r.phaseY, r.pixelX, r.pixelY))\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Exit 0 when the image matches the signature, 1 when it does not.\")\n        @Argument(help: \"The image.\") var image: String\n        @Argument(help: \"The signature: vw1 text, or a file holding vw1 text or JSON.\") var signature: String\n\n        func run() throws {\n            guarded {\n                let r = try Watermark.match(try loadImage(image), against: try WatermarkCommand.signature(signature))\n                print(String(format: \"%@ (score %.4f, %d bits, z %.1f)\", r.matched ? \"match\" : \"no match\", r.score, r.bitsCompared, r.zScore))\n                if !r.matched { throw ExitCode(1) }\n            }\n        }\n    }\n\n    struct Accept: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"accept\", abstract: \"v1's acceptance run on a seeded final_mixed sample: crops, JPEG, false matches, the kill criterion.\")\n        @Option(help: \"Images to sample (half real, half generated).\") var n: Int = 200\n        @Option(help: \"final_mixed's folder (manifest.csv) or a dataset.jsonl (default: final_mixed under VEILGARDE_DATASETS, else the work area's datasets/).\") var dataset: String?\n        @Option(help: \"The sample's and the crops' seed.\") var seed: UInt64 = 0\n        @Option(help: \"Grid phases in pixels, comma-separated.\") var phases: String = \"0,8,16,24\"\n        @Option(help: \"Write the report JSON here.\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let engine = TrainingEngine(area: try workArea.resolve(), parent: ShippedBundle.directory)\n                guard let dataset = dataset.map(datasetURL) ?? WorkArea.datasets().map({ $0.appendingPathComponent(\"final_mixed\") }) else {\n                    throw VeilGardeFailure.usage(\"no dataset: pass --dataset or set VEILGARDE_DATASETS\")\n                }\n                let manifest = try engine.manifest(for: dataset, samplePerLabel: max(1, n / 2), seed: seed)\n                var settings = AcceptanceSettings()\n                settings.seed = seed\n                settings.phases = phases.split(separator: \",\").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }\n                note(\"accept: \\(manifest.count) images from \\(dataset.path)\")\n                // Each image's row as it is measured, so a long run that stops keeps what it measured.\n                let rowsURL = out.map { datasetURL($0).deletingPathExtension().appendingPathExtension(\"rows.jsonl\") }\n                let rows = try rowsURL.map { try JSONLWriter(url: $0, truncate: true) }\n                let report = try WatermarkAcceptance.run(manifest.records.map { (manifest.url($0), $0.label) }, settings: settings, note: note,\n                                                         measured: { try? rows?.append($0) })\n                let s = report.summary\n                print(String(format: \"images %d; self-match %.1f%%; crop matched with its offset %.1f%%; JPEG q75 median score %.3f\", s.images, s.selfMatchRate * 100,\n                             s.cropMatchRate * 100, s.jpegMedianScore))\n                print(String(format: \"cross-image false matches at 0.75: %.1f%% (median cross score %.3f)\", s.crossFalseMatchRate * 100, s.crossMedianScore))\n                if let t = s.operatingThreshold { print(String(format: \"operating point: threshold %.2f, crop recall %.1f%%, false matches %.1f%%\", t, (s.operatingRecall ?? 0) * 100, (s.operatingFalseMatchRate ?? 0) * 100)) }\n                print(\"bit balance (E, S, SE, NE): \" + s.bitBalance.map { String(format: \"%.3f\", $0) }.joined(separator: \", \"))\n                for (k, v) in s.resizedMatchRate.sorted(by: { $0.key > $1.key }) {\n                    print(String(format: \"resized %@× (every %d-th image): matched %.1f%%\", k, settings.resizeEvery, v * 100))\n                }\n                print(s.killed ? \"v1 KILLED: \" + s.reasons.joined(separator: \"; \") : \"v1 passes its acceptance\")\n                if let out { try JSONCoding.write(report, to: datasetURL(out)); note(\"report: \\(out)\") }\n            }\n        }\n    }\n\n    struct Invariance: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"invariance\", abstract: \"Sign images exactly as `sign` does and record each signature; with --baseline, exit 1 on any difference.\",\n            discussion: \"A gate for changes near the warp residual: take the baseline before the change and re-run after every build. One MLX workload.\")\n        @Option(help: \"A folder (searched recursively), a text file of image paths, or an image; repeatable.\") var images: [String]\n        @Option(help: \"A previous invariance report to compare against.\") var baseline: String?\n        @Option(help: \"Write the report here.\") var out: String\n\n        func run() throws {\n            guarded {\n                let urls = try images.flatMap(imageInputs)\n                guard !urls.isEmpty else { throw VeilGardeFailure.usage(\"no images found in \\(images.joined(separator: \", \"))\") }\n                note(\"invariance: \\(urls.count) images\")\n                let started = Date()\n                let report = WatermarkInvariance.measure(urls, note: note)\n                try JSONCoding.write(report, to: datasetURL(out))\n                print(String(format: \"signed %d images (%d skipped) in %.1fs\", report.images.count, report.skipped.count, Date().timeIntervalSince(started)))\n                for s in report.skipped { print(\"skipped \\(s)\") }\n                note(\"report: \\(out)\")\n                guard let baseline else { return }\n                let reference = try JSONCoding.read(InvarianceReport.self, from: datasetURL(baseline))\n                let differences = WatermarkInvariance.compare(baseline: reference, current: report)\n                if differences.isEmpty {\n                    print(\"invariant: all \\(reference.images.count) signatures equal the baseline\")\n                    return\n                }\n                for d in differences { print(\"DIFFERENT \\(d.path) \\(d.field): \\(d.baseline) → \\(d.current)\") }\n                print(\"\\(differences.count) differences from the baseline\")\n                throw ExitCode(1)\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Commands/Weights.swift","status":"added","lang":"swift","hunks":[[1,0,1,136]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1712,"scopes":[["S","WeightsCommand",null,"",18,18,[18,39],136,null,-1,0,"a"],["S","List",null,"",22,22,[22,33],36,null,0,0,"a"],["f","run",[],"",26,26,[26,26],35,null,1,0,"a"],["S","Verify",null,"",38,38,[38,35],56,null,0,0,"a"],["f","run",[],"",42,42,[42,26],55,null,3,0,"a"],["S","ImportDINOv2",null,"",58,58,[58,41],87,null,0,0,"a"],["f","run",[],"",69,69,[69,26],86,null,5,0,"a"],["S","ExportXXSmall",null,"",89,89,[89,42],107,null,0,0,"a"],["f","run",[],"",96,96,[96,26],106,null,7,0,"a"],["f","describe",["_"],"static",109,109,[109,70],120,null,0,0,"a"],["S","ImportCLIP",null,"",122,122,[122,39],135,null,0,0,"a"],["f","run",[],"",128,128,[128,26],134,null,10,0,"a"]],"old":"","new":"//\n//  Weights.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: `veilgarde weights`: where the neural weights are and whether they are the ones the bundle\n//        was built with. `list` shows each weight's search result; `verify` re-hashes them against\n//        the shipped manifest and exits 1 on a mismatch or a missing file. `import-dinov2` builds\n//        the three DINOv2 files from Hugging Face's\n//        checkpoint (downloading it when no file is named), `export-xxsmall` quantizes an xsmall\n//        file, and `import-clip` converts CLIP's vision tower from a safetensors checkpoint.\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\nstruct WeightsCommand: ParsableCommand {\n    static let configuration = CommandConfiguration(commandName: \"weights\", abstract: \"List and verify the DINOv2, noiseprint and CLIP weights.\",\n                                                    subcommands: [List.self, Verify.self, ImportDINOv2.self, ExportXXSmall.self, ImportCLIP.self])\n\n    struct List: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"list\", abstract: \"Show where each weight file is found, in search order.\")\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first.\") var weightsDir: String?\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n                print(\"search path: \" + WeightLocator.shared.searchPath().map(\\.path).joined(separator: \" → \"))\n                for file in WeightFile.allCases {\n                    print(\"  \" + file.rawValue.padding(toLength: 34, withPad: \" \", startingAt: 0) + (WeightLocator.shared.url(file)?.path ?? \"not found\"))\n                }\n            }\n        }\n    }\n\n    struct Verify: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"verify\", abstract: \"Re-hash each weight against the hash the shipped manifest records.\")\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first.\") var weightsDir: String?\n\n        func run() throws {\n            guarded {\n                ShippedBundle.registerWeightFolders()\n                if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n                var failures = 0\n                for expected in ShippedBundle.manifest.weights {\n                    guard let url = WeightLocator.shared.url(named: expected.file) else { print(\"missing  \\(expected.file)\"); failures += 1; continue }\n                    let sha = try ArtifactHashCache.shared.sha256(url)\n                    print(\"\\(sha == expected.sha256 ? \"ok      \" : \"MISMATCH\") \\(expected.file)  \\(sha.prefix(12))  \\(url.path)\")\n                    if sha != expected.sha256 { failures += 1 }\n                }\n                if failures > 0 { throw ArgumentParser.ExitCode(FailureCode.doctor.rawValue) }\n            }\n        }\n    }\n\n    struct ImportDINOv2: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"import-dinov2\", abstract: \"Build dinov2_small, _xsmall and _xxsmall from Hugging Face's facebook/dinov2-small checkpoint.\",\n            discussion: \"With no --from, the checkpoint is downloaded into <work area>/hf. A file already in the output folder is compared tensor by tensor and kept; the new one goes to <out>/imported unless --replace.\")\n        @Option(help: \"The checkpoint: a model.safetensors, or a folder holding one.\") var from: String?\n        @Option(help: \"The output folder (default: <work area>/weights).\") var out: String?\n        @Option(help: \"small, xsmall, xxsmall or all.\") var variant: String = \"all\"\n        @Flag(help: \"Replace files already in the output folder.\") var replace = false\n        @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first for the files to compare against.\") var weightsDir: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                ShippedBundle.registerWeightFolders(workArea: area)\n                if let weightsDir { WeightLocator.shared.setOverride(datasetURL(weightsDir)) }\n                let variants: [DinoVariant]\n                if variant == \"all\" { variants = DinoVariant.allCases } else {\n                    guard let v = DinoVariant(rawValue: variant) else { throw VeilGardeFailure.usage(\"--variant is small, xsmall, xxsmall or all, not \\(variant)\") }\n                    variants = [v]\n                }\n                let checkpoint = try Dinov2Import.checkpoint(from.map(datasetURL), hfBase: area.root.appendingPathComponent(\"hf\", isDirectory: true))\n                let output = out.map(datasetURL) ?? area.weights\n                let report = try Dinov2Import.importWeights(checkpoint: checkpoint, variants: variants, output: output, replace: replace,\n                                                            reference: { WeightLocator.shared.url($0.weightFile) }, note: note)\n                print(\"checkpoint \\(report.checkpoint) (sha256 \\(report.checkpointSHA256.prefix(12)))\")\n                for file in report.files { print(WeightsCommand.describe(file)) }\n            }\n        }\n    }\n\n    struct ExportXXSmall: ParsableCommand {\n        static let configuration = CommandConfiguration(\n            commandName: \"export-xxsmall\", abstract: \"Quantize an xsmall DINOv2 file into xxsmall (8-bit Linear weights in groups of 64), as the runtime quantizes it.\")\n        @Option(help: \"The xsmall file (default: the one the weight search finds).\") var from: String?\n        @Option(help: \"The output file (default: <work area>/weights/imported/dinov2_small_xxsmall.safetensors).\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let area = try workArea.resolve()\n                ShippedBundle.registerWeightFolders(workArea: area)\n                guard let source = from.map(datasetURL) ?? WeightLocator.shared.url(.dinov2XSmall) else {\n                    throw VeilGardeFailure.missing(\"no xsmall DINOv2 file found; name one with --from\")\n                }\n                let output = out.map(datasetURL) ?? area.weights.appendingPathComponent(\"imported/\\(WeightFile.dinov2XXSmall.rawValue)\")\n                print(WeightsCommand.describe(try Dinov2Import.exportXXSmall(fromXSmall: source, to: output, reference: WeightLocator.shared.url(.dinov2XXSmall))))\n            }\n        }\n    }\n\n    static func describe(_ file: Dinov2Import.ImportedFile) -> String {\n        var line = \"\\(file.variant): \\(file.tensors) tensors → \\(file.path) (sha256 \\(file.sha256.prefix(12)))\"\n        if file.keptExisting { line += \"; the existing file was kept\" }\n        if let c = file.comparison {\n            if c.sameFile { line += \"\\n  byte-identical to \\(c.reference)\" } else {\n                line += \"\\n  against \\(c.reference): \\(c.identicalBytes) of \\(c.tensors) tensors byte-identical, max |Δ| \\(String(format: \"%.3g\", c.maxAbsDifference))\"\n                    + (c.worst.map { \" (\\($0))\" } ?? \"\")\n                for problem in c.problems.prefix(6) { line += \"\\n  \\(problem)\" }\n            }\n        }\n        return line\n    }\n\n    struct ImportCLIP: ParsableCommand {\n        static let configuration = CommandConfiguration(commandName: \"import-clip\", abstract: \"Convert CLIP ViT-B/32's vision tower from a Hugging Face safetensors file into the work area's weights.\")\n        @Option(help: \"The checkpoint: a CLIPModel model.safetensors (or a vision-only one).\") var from: String\n        @Option(help: \"The output file (default: <work area>/weights/clip_vit_b32_vision.safetensors).\") var out: String?\n        @OptionGroup var workArea: WorkAreaOptions\n\n        func run() throws {\n            guarded {\n                let output = try out.map(datasetURL) ?? workArea.resolve().root.appendingPathComponent(\"weights/\\(WeightFile.clipVision.rawValue)\")\n                let report = try CLIPImport.convert(from: datasetURL(from), to: output)\n                print(\"\\(report.tensors) tensors → \\(report.output) (sha256 \\(report.sha256.prefix(12)))\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/Options.swift","status":"added","lang":"swift","hunks":[[1,0,1,230]],"header":{"lines":[1,9],"target":"VeilGardeCLI","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1724,"scopes":[["S","WorkAreaOptions",null,"",16,16,[16,42],27,null,-1,0,"a"],["f","resolve",[],"",20,20,[20,38],26,null,0,0,"a"],["f","guarded",["_"],"",30,30,[30,40],42,[29,29],-1,0,"a"],["f","guardedAsync",["_"],"",45,45,[45,57],57,[44,44],-1,0,"a"],["f","note",["_"],"",60,60,[60,26],60,[59,59],-1,8,"a"],["S","DetectionOptions",null,"",63,63,[63,43],113,[62,62],-1,0,"a"],["f","config",[],"",87,87,[87,44],103,null,5,0,"a"],["f","config",["bundle"],"",106,106,[106,66],112,[105,105],5,0,"a"],["S","BaseExpertOptions",null,"",116,116,[116,44],124,[115,115],-1,0,"a"],["f","resolve",[],"",120,120,[120,40],123,null,8,0,"a"],["f","loadImage",["_"],"",127,127,[127,49],129,[126,126],-1,0,"a"],["f","imageInputs",["_"],"",133,133,[133,50],150,[131,132],-1,0,"a"],["f","emitJSON",["_","to"],"",153,153,[153,59],160,[152,152],-1,0,"a"],["f","timed",["_"],"",163,163,[163,62],167,[162,162],-1,0,"a"],["S","RouteOptions",null,"",170,170,[170,39],224,[169,169],-1,0,"a"],["f","config",[],"",192,192,[192,44],223,null,14,0,"a"],["f","parseHint",["_"],"",226,226,[226,58],230,null,-1,0,"a"]],"old":"","new":"//\n//  Options.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The options every command shares: the work area (--work-area, else VEILGARDE_WORK_AREA,\n//        else refused), the failure mapping to sysexits so scripts can branch, and the stderr note\n//        every progress line goes through.\n//\n\nimport ArgumentParser\nimport CoreGraphics\nimport Foundation\nimport VeilGarde\n\nstruct WorkAreaOptions: ParsableArguments {\n    @Option(name: .customLong(\"work-area\"), help: \"Where VeilGarde's data lives (default: VEILGARDE_WORK_AREA).\")\n    var workAreaPath: String?\n\n    func resolve() throws -> WorkArea {\n        if let workAreaPath { return WorkArea(root: URL(fileURLWithPath: (workAreaPath as NSString).expandingTildeInPath, isDirectory: true)) }\n        guard let area = WorkArea.resolve() else {\n            throw VeilGardeFailure.configuration(\"no work area\", hint: \"set VEILGARDE_WORK_AREA or pass --work-area: VeilGarde writes no data it was not told where to put\")\n        }\n        return area\n    }\n}\n\n/// Runs a command body, printing a VeilGardeFailure and exiting with its code; other errors are internal.\nfunc guarded(_ body: () throws -> Void) {\n    do {\n        try body()\n    } catch let failure as VeilGardeFailure {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(failure.description)\\n\".utf8))\n        exit(failure.code.rawValue)\n    } catch let exit as ArgumentParser.ExitCode {\n        Foundation.exit(exit.rawValue)\n    } catch {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(error)\\n\".utf8))\n        exit(FailureCode.internalError.rawValue)\n    }\n}\n\n/// The async form of `guarded`.\nfunc guardedAsync(_ body: () async throws -> Void) async {\n    do {\n        try await body()\n    } catch let failure as VeilGardeFailure {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(failure.description)\\n\".utf8))\n        exit(failure.code.rawValue)\n    } catch let exit as ArgumentParser.ExitCode {\n        Foundation.exit(exit.rawValue)\n    } catch {\n        FileHandle.standardError.write(Data(\"veilgarde: \\(error)\\n\".utf8))\n        exit(FailureCode.internalError.rawValue)\n    }\n}\n\n/// A progress line, to stderr.\nfunc note(_ text: String) { FileHandle.standardError.write(Data((text + \"\\n\").utf8)) }\n\n/// The flags every detection command shares, mapped onto an InferenceConfig.\nstruct DetectionOptions: ParsableArguments {\n    @Option(help: \"Presentation patch size in pixels, a multiple of 32 (the sensor lane is always the 32-px grid).\")\n    var patch: Int = 32\n    @Option(help: \"A base warp model to score with instead of the shipped one (XGBoost JSON).\")\n    var model: String?\n    @Flag(help: \"Run MLX on the CPU (an A/B check that the hot path normally runs on the GPU).\")\n    var cpu = false\n    @Flag(name: .customLong(\"exact-warp\"), help: \"Exact double warp coordinates instead of cv2's 1/32-pixel quantization (debugging only).\")\n    var exactWarp = false\n    @Option(help: \"Hotspot blend: off, asymmetric or symmetric.\")\n    var hotspot: String = HotspotMode.symmetric.rawValue\n    @Option(help: \"The weighted verdict's threshold (default 0.56).\")\n    var threshold: Float?\n    @Option(help: \"The weighted verdict's inconclusive band (default 0.04).\")\n    var band: Float?\n    @Flag(name: .customLong(\"native-check\"), help: \"Also score the native-resolution centre crop and report the disagreement.\")\n    var nativeCheck = false\n    @Flag(name: .customLong(\"full-res\"), help: \"Analyse at native resolution (no 512 cap; out of the model's training distribution).\")\n    var fullRes = false\n    @Flag(help: \"Per-phase timings on stderr.\")\n    var timing = false\n    @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first for the DINOv2, noiseprint and CLIP weights.\")\n    var weightsDir: String?\n\n    func config() throws -> InferenceConfig {\n        ShippedBundle.registerWeightFolders()\n        if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n        guard patch > 0, patch % 32 == 0 else { throw VeilGardeFailure.usage(\"--patch must be a positive multiple of 32, not \\(patch)\") }\n        guard let mode = HotspotMode(rawValue: hotspot) else { throw VeilGardeFailure.usage(\"--hotspot must be off, asymmetric or symmetric, not \\(hotspot)\") }\n        var config = InferenceConfig()\n        if let model { config.modelURL = URL(fileURLWithPath: (model as NSString).expandingTildeInPath) }\n        config.warp.patchSize = patch\n        config.warp.quantizeLikeCV2 = !exactWarp\n        config.warp.hotspot.mode = mode\n        config.warp.nativeCheck = nativeCheck\n        config.warp.fullResolution = fullRes\n        if let threshold { config.decision.threshold = threshold }\n        if let band { config.decision.band = band }\n        config.timing = timing\n        return config\n    }\n\n    /// The same, reading every model from `bundle`; a --model override still wins for the base warp model.\n    func config(bundle: DetectorBundle) throws -> InferenceConfig {\n        var config = try config()\n        let modelOverride = model.map { _ in config.modelURL }\n        config.rebind(to: bundle)\n        if let modelOverride { config.modelURL = modelOverride }\n        return config\n    }\n}\n\n/// `--base`: the camera domain's base expert, the fusion head unless a study asks for the warp lens alone.\nstruct BaseExpertOptions: ParsableArguments {\n    @Option(name: .customLong(\"base\"), help: \"The camera base expert: fusion (the detector) or warp (the warp lens alone at 0.56 ± 0.04, a measurement mode).\")\n    var base: String = BaseExpert.fusion.rawValue\n\n    func resolve() throws -> BaseExpert {\n        guard let expert = BaseExpert(rawValue: base) else { throw VeilGardeFailure.usage(\"--base is fusion or warp, not \\(base)\") }\n        return expert\n    }\n}\n\n/// Reads an image the way the detector sees it (EXIF orientation applied).\nfunc loadImage(_ path: String) throws -> CGImage {\n    try ImageDecoding.cgImage(contentsOf: URL(fileURLWithPath: (path as NSString).expandingTildeInPath))\n}\n\n/// The images an argument names: a text file of paths (one per line, `#` comments), a folder\n/// (searched recursively, sorted by path, exFAT sidecars skipped), or one image.\nfunc imageInputs(_ input: String) throws -> [URL] {\n    let url = datasetURL(input)\n    if url.pathExtension == \"txt\" {\n        let text = try String(contentsOf: url, encoding: .utf8)\n        return text.split(separator: \"\\n\").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty && !$0.hasPrefix(\"#\") }.map(datasetURL)\n    }\n    var isDirectory: ObjCBool = false\n    guard FileManager.default.fileExists(atPath: url.path, isDirectory: &isDirectory) else { throw VeilGardeFailure.missing(\"no image or folder at \\(url.path)\") }\n    guard isDirectory.boolValue else { return [url] }\n    var out: [URL] = []\n    let walker = FileManager.default.enumerator(at: url, includingPropertiesForKeys: [.isRegularFileKey], options: [.skipsHiddenFiles])\n    while let next = walker?.nextObject() as? URL {\n        let name = next.lastPathComponent\n        guard !name.hasPrefix(\"._\"), ShardExtractor.imageExtensions.contains(next.pathExtension.lowercased()) else { continue }\n        out.append(next)\n    }\n    return out.sorted { $0.path < $1.path }\n}\n\n/// Writes JSON to stdout with a trailing newline (`--json -`), or to a file.\nfunc emitJSON(_ data: Data, to destination: String) throws {\n    if destination == \"-\" {\n        FileHandle.standardOutput.write(data)\n        FileHandle.standardOutput.write(Data(\"\\n\".utf8))\n    } else {\n        try data.write(to: URL(fileURLWithPath: (destination as NSString).expandingTildeInPath))\n    }\n}\n\n/// Wall seconds of `body`.\nfunc timed<T>(_ body: () throws -> T) rethrows -> (T, Double) {\n    let t0 = DispatchTime.now()\n    let value = try body()\n    return (value, Double(DispatchTime.now().uptimeNanoseconds - t0.uptimeNanoseconds) / 1e9)\n}\n\n/// The router's flags, shared by `route` and `batch`.\nstruct RouteOptions: ParsableArguments {\n    @Option(name: .customLong(\"semantic-profile\"), help: \"control, semantic_diagnostic_only or semantic_removed.\")\n    var semanticProfile: String = SemanticResponsibility.control.rawValue\n    @Option(name: .customLong(\"result-surface\"), help: \"warp-sensor or legacy-semantic.\")\n    var resultSurface: String = ResultSurface.warpSensor.rawValue\n    @Option(name: .customLong(\"majority-model\"), help: \"A candidate sensor model (needs --majority-calibration).\")\n    var majorityModel: String?\n    @Option(name: .customLong(\"majority-calibration\"), help: \"Its calibration contract (needs --majority-model).\")\n    var majorityCalibration: String?\n    @Flag(name: .customLong(\"render-taxonomy\"), help: \"Re-enable the suspended render taxonomy (campaign use).\")\n    var renderTaxonomy = false\n    @Flag(name: .customLong(\"zoom-escalation\"), help: \"Re-enable the disabled zoom escalation (campaign use).\")\n    var zoomEscalation = false\n    @Flag(name: .customLong(\"x-domain-gate\"), help: \"Enable the v0 x-domain trust gate (surfacing only).\")\n    var xDomainGate = false\n    @Option(help: \"DINOv2 weights: small (F32), xsmall (F16) or xxsmall (int8).\")\n    var dino: String = DinoVariant.small.rawValue\n    @Option(help: \"A bundle directory to detect with instead of the shipped one (the flywheel's live/ or a candidate).\")\n    var bundle: String?\n    @Option(name: .customLong(\"weights-dir\"), help: \"A folder searched first for the DINOv2, noiseprint and CLIP weights.\")\n    var weightsDir: String?\n\n    func config() throws -> InferenceConfig {\n        ShippedBundle.registerWeightFolders()\n        if let weightsDir { WeightLocator.shared.setOverride(URL(fileURLWithPath: (weightsDir as NSString).expandingTildeInPath, isDirectory: true)) }\n        let detectorBundle = try bundle.map { try DetectorBundle.load(URL(fileURLWithPath: ($0 as NSString).expandingTildeInPath, isDirectory: true)) } ?? .shipped\n        var config = InferenceConfig(bundle: detectorBundle)\n        guard let profile = SemanticResponsibility(rawValue: semanticProfile) else {\n            throw VeilGardeFailure.usage(\"--semantic-profile must be control, semantic_diagnostic_only or semantic_removed, not \\(semanticProfile)\")\n        }\n        guard let surface = ResultSurface(rawValue: resultSurface) else {\n            throw VeilGardeFailure.usage(\"--result-surface must be warp-sensor or legacy-semantic, not \\(resultSurface)\")\n        }\n        guard let variant = DinoVariant(rawValue: dino) else { throw VeilGardeFailure.usage(\"--dino must be small, xsmall or xxsmall, not \\(dino)\") }\n        config.mechanisms.semanticResponsibility = profile\n        config.mechanisms.resultSurface = surface\n        config.mechanisms.renderTaxonomy = renderTaxonomy\n        config.mechanisms.zoomEscalation = zoomEscalation\n        config.mechanisms.xDomainGate = xDomainGate\n        config.dinoVariant = variant\n        // A calibration binds to its model's SHA-256: the two are given together or not at all.\n        switch (majorityModel, majorityCalibration) {\n        case let (model?, calibration?):\n            config.majoritySensorModelURL = URL(fileURLWithPath: (model as NSString).expandingTildeInPath)\n            config.sensorCalibrationURL = URL(fileURLWithPath: (calibration as NSString).expandingTildeInPath)\n        case (nil, nil):\n            break\n        case (_?, nil):\n            throw VeilGardeFailure.usage(\"--majority-model needs a paired --majority-calibration (a model without its contract cannot be trusted)\")\n        case (nil, _?):\n            throw VeilGardeFailure.usage(\"--majority-calibration needs a paired --majority-model (a contract binds to its model's SHA-256)\")\n        }\n        return config\n    }\n}\n\nfunc parseHint(_ raw: String?) throws -> DetectionDomain? {\n    guard let raw else { return nil }\n    guard let hint = DetectionDomain(rawValue: raw) else { throw VeilGardeFailure.usage(\"--hint must be camera or screenshot, not \\(raw)\") }\n    return hint\n}\n"},{"path":"Sources/VeilGardeCLI/Output/PatchMap.swift","status":"added","lang":"swift","hunks":[[1,0,1,135]],"header":{"lines":[1,11],"target":"VeilGardeCLI","what":[6,8],"pin":[9,10],"in":null,"out":null,"style":"swift"},"marks":[],"first":1741,"scopes":[["E","PatchMap",null,"",16,16,[16,14],135,null,-1,0,"a",[]],["f","confidence",["_","threshold"],"static",18,18,[18,71],23,[17,17],0,0,"a"],["f","heat",["_"],"static",26,26,[26,52],32,[25,25],0,0,"a"],["f","lerp",["_","_","_"],"",27,27,[27,93],29,null,2,4,"a"],["f","weightColor",["_"],"static",34,34,[34,62],37,null,0,0,"a"],["f","cell",["_","bg","color"],"static",39,39,[39,81],43,null,0,0,"a"],["f","word",["_","color"],"static",45,45,[45,60],54,null,0,0,"a"],["f","sourceLabel",["_"],"static",56,56,[56,62],63,null,0,0,"a"],["f","majorityDetail",["_"],"static",65,65,[65,65],72,null,0,0,"a"],["f","render",["_","imagePath","model","times","device","color"],"static",74,74,[74,135],134,null,0,0,"a"]],"old":"","new":"//\n//  PatchMap.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The terminal report of one detection: the P(generated) map in green, yellow and red, the\n//        base verdict's weight map in blue, the weighted and majority verdicts with their trust,\n//        the native check, the capture signature and the run times.\n//  PIN:  Garde's printPretty layout, so a reader who knows `garde photo.jpg` reads this the same way.\n//        Colour only on a terminal, never under --no-color or a JSON-to-stdout run.\n//\n\nimport Foundation\nimport VeilGarde\n\nenum PatchMap {\n    /// Distance from the threshold, not from 0.5 (the reference `_confidence_label`).\n    static func confidence(_ score: Float, threshold: Float) -> String {\n        let dev = abs(score - threshold)\n        if dev >= 0.3 { return \"high\" }\n        if dev >= 0.15 { return \"medium\" }\n        return \"low\"\n    }\n\n    /// Green (real) → yellow (uncertain) → red (generated).\n    static func heat(_ p: Float) -> (Int, Int, Int) {\n        func lerp(_ a: (Int, Int, Int), _ b: (Int, Int, Int), _ u: Float) -> (Int, Int, Int) {\n            (Int(Float(a.0) + (Float(b.0) - Float(a.0)) * u), Int(Float(a.1) + (Float(b.1) - Float(a.1)) * u), Int(Float(a.2) + (Float(b.2) - Float(a.2)) * u))\n        }\n        let t = max(0, min(1, p))\n        return t < 0.5 ? lerp((35, 150, 65), (214, 175, 40), t * 2) : lerp((214, 175, 40), (205, 55, 48), (t - 0.5) * 2)\n    }\n\n    static func weightColor(_ frac: Float) -> (Int, Int, Int) {\n        let t = max(0, min(1, frac))\n        return (Int(25 + 35 * t), Int(35 + 90 * t), Int(55 + 180 * t))\n    }\n\n    static func cell(_ text: String, bg: (Int, Int, Int), color: Bool) -> String {\n        guard color else { return text }\n        let lum = 0.299 * Double(bg.0) + 0.587 * Double(bg.1) + 0.114 * Double(bg.2)\n        return \"\\u{1B}[48;2;\\(bg.0);\\(bg.1);\\(bg.2)m\\u{1B}[\\(lum > 145 ? \"30\" : \"97\")m\\(text)\\u{1B}[0m\"\n    }\n\n    static func word(_ word: String, color: Bool) -> String {\n        guard color else { return word }\n        let code: String\n        switch word {\n        case \"generated\": code = \"31\"\n        case \"inconclusive\", \"render\": code = \"33\"\n        default: code = \"32\"\n        }\n        return \"\\u{1B}[\\(code);1m\\(word)\\u{1B}[0m\"\n    }\n\n    static func sourceLabel(_ source: ResultSource) -> String {\n        switch source {\n        case .warpSensor: return \"warp sensor\"\n        case .screenshotContent: return \"screenshot content\"\n        case .semanticTiles: return \"semantic tiles\"\n        case .none: return \"none\"\n        }\n    }\n\n    static func majorityDetail(_ source: ResultSource) -> String {\n        switch source {\n        case .warpSensor: return \"the camera-sensor score under its contract: as shipped, the tile vote itself, called by two cuts\"\n        case .screenshotContent: return \"the screenshot content head's probability\"\n        case .semanticTiles: return \"the semantic token vote (legacy payload)\"\n        case .none: return \"source unavailable\"\n        }\n    }\n\n    static func render(_ r: InferenceResult, imagePath: String, model: String, times: [Double], device: String, color: Bool) -> String {\n        var out = \"VeilGarde — \\(URL(fileURLWithPath: imagePath).lastPathComponent)\\n\"\n        out += \"image \\(r.imageWidth)×\\(r.imageHeight) · grid \\(r.gridRows)×\\(r.gridCols) @ \\(r.patchSize) px · device \\(device) · scorer \\(r.scorer) · \\(model)\\n\\n\"\n        var header = \"     \"\n        for j in 0..<r.gridCols { header += String(format: \"  %2d  \", j) }\n        if r.tileMapSource != .none && r.patches.count >= r.gridRows * r.gridCols {\n            out += \"P(generated) [\\(sourceLabel(r.tileMapSource)) map] — green real · yellow uncertain · red generated\\n\" + header + \"\\n\"\n            for i in 0..<r.gridRows {\n                var line = String(format: \" %2d  \", i)\n                for j in 0..<r.gridCols {\n                    let p = r.patches[i * r.gridCols + j].pGenerated\n                    line += cell(String(format: \" %3.0f%% \", p * 100), bg: heat(p), color: color)\n                }\n                out += line + \"\\n\"\n            }\n            out += String(format: \"\\nbase-verdict contribution — %.1f%% shown (center × texture × confidence)\\n\", min(1, max(0, r.visibleBaseWeightShare)) * 100)\n            out += header + \"\\n\"\n            let maxW = max(r.patches.map(\\.weight).max() ?? 1, 1e-9)\n            for i in 0..<r.gridRows {\n                var line = String(format: \" %2d  \", i)\n                for j in 0..<r.gridCols {\n                    let w = r.patches[i * r.gridCols + j].weight\n                    line += cell(String(format: \" %4.1f \", w * 100), bg: weightColor(w / maxW), color: color)\n                }\n                out += line + \"\\n\"\n            }\n        } else {\n            out += \"tile map [none] — this route did not produce spatial sensor evidence\\n\"\n        }\n        if r.isScreenshot { out += \"\\nscreenshot/content route — no native camera-sensor map; the weighted verdict governs\\n\" }\n        out += \"\\nverdict  weighted  \\(String(format: \"%.4f\", r.weightedScore))  \" + word(r.weightedPrediction, color: color)\n        out += \"  (\\(confidence(r.weightedScore, threshold: r.decisionThreshold)) confidence\" + String(format: \" · T=%.2f ±%.2f)\\n\", r.decisionThreshold, r.uncertainBand)\n        out += \"         majority  \\(String(format: \"%.4f\", r.majorityScore))  \" + word(r.majorityPrediction, color: color)\n        let trust = Trust.physicsVote(r)\n        out += \"  [\\(sourceLabel(r.majoritySource)) · \\(trust == \"taxonomy\" ? \"taxonomy\" : \"\\(trust) trust\")]  (\\(majorityDetail(r.majoritySource)))\\n\"\n        if let raw = r.sensorRawProbability, r.majoritySource == .warpSensor {\n            if let cuts = r.sensorCalibration?.cuts {\n                out += String(format: \"sensor   tile vote %.4f against two cuts: real at or under %.4f, generated at or over %.4f\\n\", raw, cuts.realAtOrBelow, cuts.generatedAtOrAbove)\n            } else {\n                out += String(format: \"sensor   raw tile fraction %.4f → calibrated %.4f\", raw, r.sensorProbability ?? raw) + \" (\\(r.sensorCalibration?.identity ?? \"none\"))\\n\"\n            }\n        }\n        if let ns = r.nativeScore, let nd = r.nativeDisagreement {\n            out += String(format: \"native   weighted  %.4f  (center crop at native resolution · Δ %.4f%@)\\n\", ns, nd, nd > 0.08 ? \" — DOMAIN SHIFT: resized and native scores disagree\" : \"\")\n        }\n        if let cs = r.captureSignature {\n            let tag: String\n            if !cs.valid { tag = \"abstain (native \\(cs.nativePixels)px < 512 — too small or degraded to judge)\" } else if cs.present { tag = \"real-sensor signature PRESENT\" } else { tag = \"absent (generated, OR a degraded or shared real)\" }\n            let w = !cs.valid ? \"inconclusive\" : (cs.present ? \"real\" : \"generated\")\n            out += String(format: \"capture  peak %.1f  \", cs.peak) + word(w, color: color) + \"  (\\(tag))\\n\"\n        }\n        if let specialists = r.specialists, !specialists.isEmpty {\n            out += \"\\nspecialists\\n\"\n            for s in specialists {\n                out += \"  \" + s.name.padding(toLength: 16, withPad: \" \", startingAt: 0) + String(format: \" P(AI) %.4f  \", s.pAI)\n                    + word(s.verdict, color: color) + String(format: \"  weight %.2f\\n\", s.weight)\n            }\n        }\n        out += \"time     \" + times.enumerated().map { i, t in String(format: \"%.3fs%@\", t, i == 0 && times.count > 1 ? \" (warmup)\" : \"\") }.joined(separator: \" · \") + \"\\n\"\n        return out\n    }\n}\n"},{"path":"Sources/VeilGardeCLI/VeilGardeCommand.swift","status":"added","lang":"swift","hunks":[[1,0,1,32]],"header":{"lines":[1,12],"target":"VeilGardeCLI","what":[6,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":1751,"scopes":[["S","VeilGardeCommand",null,"",18,19,[19,46],32,null,-1,0,"a"],["f","run",[],"",29,29,[29,28],31,null,0,0,"a"]],"old":"","new":"//\n//  VeilGardeCommand.swift\n//  VeilGardeCLI\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The `veilgarde` root command. Bare `veilgarde` prints help; the subcommands detect\n//        (score, fuse, route, batch), extract and train (features, train), run the flywheel,\n//        measure what could be pruned (research), sign and match watermarks, manage weights and\n//        bundles, and prove parity with Garde.\n//  PIN:  Results go to stdout and progress to stderr, so `veilgarde route x.jpg --json | jq`\n//        stays clean. A VeilGardeFailure exits with its sysexits code (Options.swift).\n//\n\nimport ArgumentParser\nimport Foundation\nimport VeilGarde\n\n@main\nstruct VeilGardeCommand: AsyncParsableCommand {\n    static let configuration = CommandConfiguration(\n        commandName: \"veilgarde\",\n        abstract: \"VeilGarde, the AI-generated-image detector: the warp lens, its models, the flywheel that grows them, and a watermark on the same residual.\",\n        discussion: \"Start with `veilgarde doctor`. Every command writes its result to stdout; add --json where offered.\",\n        version: VeilGardeVersion.string,\n        subcommands: [DoctorCommand.self, ScoreCommand.self, FuseCommand.self, RouteCommand.self, BatchCommand.self, FeaturesCommand.self,\n                      TrainCommand.self, FlywheelCommand.self, ResearchCommand.self, WatermarkCommand.self, WeightsCommand.self, BundleCommand.self, ParityCommand.self]\n    )\n\n    func run() async throws {\n        print(VeilGardeCommand.helpMessage())\n    }\n}\n"}]};
